#[derive(Debug, Clone)]
pub struct Finding {
    pub code: String,
    pub span: Span,
    pub message: String,
    pub notes: Vec<String>,
    pub help: Option<String>,
    pub warning: bool,
}

pub fn refusal(code: &str, span: Span, message: String, notes: Vec<String>, help: String) -> Finding { Finding { code: code.to_owned(), span, message, notes, help: Some(help), warning: false } }


// --- fixed.nika ---

pub const HASHED_FROM: i64 = 12;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Table {
    pub seed: u64,
    pub disps: Vec<(u32, u32)>,
    pub keys: Vec<String>,
    pub order: Vec<i64>,
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn fnv(key: &str, seed: u64) -> u64 {
    let mut hash: u64 = 14695981039346656037u64 ^ seed;
    for b in key.bytes() {
        hash ^= b as u64;
        hash = hash.wrapping_mul(1099511628211u64);
    }
    hash
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn displace(f1: u32, f2: u32, d1: u32, d2: u32) -> u32 { d2.wrapping_add(f1.wrapping_mul(d1)).wrapping_add(f2) }

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn build(keys: &[String]) -> Option<Table> {
    let n = keys.len() as i64;
    if n < HASHED_FROM {
        let mut written: Vec<String> = vec![];
        let mut order: Vec<i64> = vec![];
        for at in 0..n {
            written.push((*nikaia_std::index::get(&keys, nikaia_std::index::at(at))).to_owned());
            order.push(at);
        }
        return Some(Table { seed: 0, disps: vec![], keys: written, order });
    }
    let mut buckets = (n + 4) / 5;
    if buckets < 1 { buckets = 1; }
    for seed in 0..200 {
        let table = attempt(keys, seed as u64, buckets, n);
        if table.is_some() { return table; }
    }
    None
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn attempt(keys: &[String], seed: u64, buckets: i64, n: i64) -> Option<Table> {
    let mut by_bucket: Vec<Vec<(i64, u32, u32)>> = vec![];
    for _ in 0..buckets { by_bucket.push(vec![]); }
    for at in 0..n {
        let hash = fnv(nikaia_std::index::get(&keys, nikaia_std::index::at(at)), seed);
        let g = (hash >> 32) as u32;
        let f1 = hash as u32;
        let f2 = (hash >> 16) as u32;
        by_bucket[nikaia_std::index::at(g as i64 % buckets)].push((at, f1, f2));
    }
    let mut order: Vec<(i64, i64)> = vec![];
    for b in 0..buckets {
        let size = (*nikaia_std::index::get(&by_bucket, nikaia_std::index::at(b))).len() as i64;
        if size > 0 { order.push((0 - size, b)); }
    }
    order.sort();
    let mut disps: Vec<(u32, u32)> = vec![];
    for _ in 0..buckets { disps.push((0, 0)); }
    let mut slots: Vec<i64> = vec![];
    for _ in 0..n { slots.push(-1); }
    for (_, bucket) in order.iter() {
        let bucket = nikaia_std::num::value(bucket);
        let mut placed = false;
        let mut d1: u32 = 0u32;
        while !placed && (d1 as i64) < n {
            let mut d2: u32 = 0u32;
            while !placed && (d2 as i64) < n {
                let mut taken: Vec<(i64, i64)> = vec![];
                let mut fits = true;
                for (at, f1, f2) in (*nikaia_std::index::get(&by_bucket, nikaia_std::index::at(bucket))).iter() {
                    let at = nikaia_std::num::value(at);let f1 = nikaia_std::num::value(f1);let f2 = nikaia_std::num::value(f2);
                    let slot = displace(f1, f2, d1, d2) as i64 % n;
                    let mut clash = *nikaia_std::index::get(&slots, nikaia_std::index::at(slot)) >= 0;
                    for t in taken.iter() { if t.0 == slot { clash = true; } }
                    if clash {
                        fits = false;
                        break;
                    }
                    taken.push((slot, at));
                }
                if fits {
                    { let __nikaia_stored = (d1, d2); nikaia_std::index::set(&mut disps, nikaia_std::index::at(bucket), __nikaia_stored); }
                    for (slot, at) in taken.iter() {
                        let slot = nikaia_std::num::value(slot);let at = nikaia_std::num::value(at);
                        { let __nikaia_stored = at; nikaia_std::index::set(&mut slots, nikaia_std::index::at(slot), __nikaia_stored); }
                    }
                    placed = true;
                }
                d2 += 1;
            }
            d1 += 1;
        }
        if !placed { return None; }
    }
    let mut written: Vec<String> = vec![];
    let mut at_of: Vec<i64> = vec![];
    for slot in slots.iter() {
        let slot = nikaia_std::num::value(slot);
        if slot < 0 { return None; }
        written.push((*nikaia_std::index::get(&keys, nikaia_std::index::at(slot))).to_owned());
        at_of.push(slot);
    }
    Some(Table { seed, disps, keys: written, order: at_of })
}


// --- fold.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Constant {
    pub magnitude: u64,
    pub negative: bool,
    pub pinned: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Folded {
    Value(Constant),
    Overflows(Constant),
    TooLarge(bool),
    Nothing,
}

const I8_LOW: u64 = 128;

const I8_HIGH: u64 = 127;

const I16_LOW: u64 = 32768;

const I16_HIGH: u64 = 32767;

const I32_LOW: u64 = 2147483648;

const I32_HIGH: u64 = 2147483647;

const I64_LOW: u64 = 9223372036854775808;

const I64_HIGH: u64 = 9223372036854775807;

const U8_HIGH: u64 = 255;

const U16_HIGH: u64 = 65535;

const U32_HIGH: u64 = 4294967295;

const U64_HIGH: u64 = 18446744073709551615;

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn fits(c: &Constant, ty: &str) -> bool {
    let (low, high) = match ty {
        "i8" => (I8_LOW, I8_HIGH),
        "i16" => (I16_LOW, I16_HIGH),
        "i32" => (I32_LOW, I32_HIGH),
        "i64" => (I64_LOW, I64_HIGH),
        "u8" => (0, U8_HIGH),
        "u16" => (0, U16_HIGH),
        "u32" => (0, U32_HIGH),
        "u64" => (0, U64_HIGH),
        _ => return true,
    };
    if c.negative { return c.magnitude <= low; }
    c.magnitude <= high
}

fn number(magnitude: u64, negative: bool, pinned: String) -> Constant { Constant { magnitude, negative: negative && magnitude != 0u64, pinned } }

fn added(a: &Constant, b_magnitude: u64, b_negative: bool, pinned: String) -> Folded {
    if a.negative == b_negative {
        let sum = a.magnitude.wrapping_add(b_magnitude);
        if sum < a.magnitude { return Folded::TooLarge(a.negative); }
        return Folded::Value(number(sum, a.negative, pinned));
    }
    if a.magnitude >= b_magnitude { return Folded::Value(number(a.magnitude - b_magnitude, a.negative, pinned)); }
    Folded::Value(number(b_magnitude - a.magnitude, b_negative, pinned))
}

fn multiplied(a: &Constant, b: &Constant, pinned: String) -> Folded {
    let negative = a.negative != b.negative;
    if a.magnitude == 0u64 { return Folded::Value(number(0u64, false, pinned)); }
    let product = a.magnitude.wrapping_mul(b.magnitude);
    if product.wrapping_div(a.magnitude) != b.magnitude { return Folded::TooLarge(negative); }
    Folded::Value(number(product, negative, pinned))
}

pub fn constant_of(expr: &Expr, name_is: &impl Fn(winnow_grammar::Symbol) -> Folded) -> Folded {
    match expr {
        Expr::LitInt { value, negative } => { let negative = *negative; let value = *value; Folded::Value(number(value, negative, String::from(""))) },
        Expr::Variable(name) => { let name = *name; name_is(name) },
        Expr::Unary { op, expr } => { let expr = nikaia_std::boxed::open(expr); negated(op, expr, name_is) },
        Expr::Binary { op, lhs, rhs, .. } => { let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs); combined(op, lhs, rhs, name_is) },
        _ => Folded::Nothing,
    }
}

fn negated(op: &UnaryOp, inner: &Expr, name_is: &impl Fn(winnow_grammar::Symbol) -> Folded) -> Folded {
    if *op != UnaryOp::Neg { return Folded::Nothing; }
    match constant_of(inner, name_is) {
        Folded::Value(c) => pinned_step(number(c.magnitude, !c.negative, c.pinned)),
        Folded::TooLarge(negative) => Folded::TooLarge(!negative),
        other => other,
    }
}

fn pinned_step(c: Constant) -> Folded { if fits(&c, &c.pinned) { Folded::Value(c) } else { Folded::Overflows(c) } }

fn combined(op: &BinaryOp, lhs: &Expr, rhs: &Expr, name_is: &impl Fn(winnow_grammar::Symbol) -> Folded) -> Folded {
    let a = match constant_of(lhs, name_is) {
        Folded::Value(c) => c,
        other => return other,
    };
    let b = match constant_of(rhs, name_is) {
        Folded::Value(c) => c,
        other => return other,
    };
    if !a.pinned.is_empty() && !b.pinned.is_empty() && a.pinned != b.pinned { return Folded::Nothing; }
    let pinned = if a.pinned.is_empty() { b.pinned.to_owned() } else { a.pinned.to_owned() };
    let folded = match op {
        BinaryOp::Add => added(&a, b.magnitude, b.negative, pinned),
        BinaryOp::Sub => added(&a, b.magnitude, !b.negative, pinned),
        BinaryOp::Mul => multiplied(&a, &b, pinned),
        BinaryOp::Div => divided(&a, &b, pinned, false),
        BinaryOp::Rem => divided(&a, &b, pinned, true),
        _ => Folded::Nothing,
    };
    match folded {
        Folded::Value(c) => pinned_step(c),
        other => other,
    }
}

fn divided(a: &Constant, b: &Constant, pinned: String, remainder: bool) -> Folded {
    if b.magnitude == 0u64 { return Folded::Nothing; }
    if remainder { return Folded::Value(number(a.magnitude % b.magnitude, a.negative, pinned)); }
    Folded::Value(number(a.magnitude / b.magnitude, a.negative != b.negative, pinned))
}

pub fn wants_widening(folded: &Folded) -> bool {
    match folded {
        Folded::Value(c) => c.pinned.is_empty() && !fits(c, "i32") && fits(c, "i64"),
        _ => false,
    }
}


// --- foreign.nika ---

#[derive(Debug, Clone)]
struct Walked {
    seen: Vec<Seen>,
    with_names: bool,
}

#[derive(Debug, Clone)]
pub enum Seen {
    Path { name: String, span: Span },
    Call { name: String, wrote: Option<Wrote>, span: Span },
    Name(String),
    Spawn,
    Opaque,
}

pub fn written_in(program: &Program, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, root_at: &impl Fn(&str) -> i64) -> Vec<Seen> {
    let mut found = Walked { seen: vec![], with_names: false };
    for item in program.items.iter() { item_names(&item.node, &item.span, names, unaliased, holes_of, root_at, &mut found); }
    found.seen
}

pub fn seen_in(block: &Block, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, root_at: &impl Fn(&str) -> i64, with_names: bool) -> Vec<Seen> {
    let mut found = Walked { seen: vec![], with_names };
    block_names(block, names, unaliased, holes_of, root_at, &mut found);
    found.seen
}

pub fn seen_in_expression(expr: &Expr, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, root_at: &impl Fn(&str) -> i64, with_names: bool) -> Vec<Seen> {
    let mut found = Walked { seen: vec![], with_names };
    let nowhere = Span::nowhere();
    expression_paths(expr, &nowhere, names, unaliased, holes_of, root_at, &mut found);
    expression_blocks(expr, names, unaliased, holes_of, root_at, &mut found);
    found.seen
}

fn item_names(item: &Item, span: &Span, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, root_at: &impl Fn(&str) -> i64, found: &mut Walked) {
    match item {
        Item::Fn { args, ret_type, body, .. } => {
            for arg in args.iter() { type_names(&arg.ty, span, names, unaliased, found); }
            maybe_type_names((ret_type).as_ref(), span, names, unaliased, found);
            block_names(body, names, unaliased, holes_of, root_at, found);
        },
        Item::Struct { fields, .. } => { for field in fields.iter() { type_names(&field.ty, span, names, unaliased, found); } },
        Item::Impl { methods, .. } => { for method in methods.iter() { item_names(&method.node, &method.span, names, unaliased, holes_of, root_at, found); } },
        _ => { },
    }
}

fn type_names(ty: &Type, span: &Span, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, found: &mut Walked) {
    let name = unaliased(names.resolve(ty.name));
    if name.contains("::") { found.seen.push(named_at(name, span)); }
    for argument in ty.generics.iter() { type_names(argument, span, names, unaliased, found); }
    maybe_type_names((*ty.code).as_ref().and_then(|__nikaia_it| (*__nikaia_it.result).as_ref()), span, names, unaliased, found);
}

fn maybe_type_names(ty: Option<&Type>, span: &Span, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, found: &mut Walked) { type_names(match ty { Some(__nikaia_value) => __nikaia_value, None => return }, span, names, unaliased, found); }

fn block_names(block: &Block, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, root_at: &impl Fn(&str) -> i64, found: &mut Walked) {
    for stmt in block.stmts.iter() {
        match &stmt.node {
            Stmt::Let { ty, .. } => maybe_type_names((ty).as_ref(), &stmt.span, names, unaliased, found),
            _ => { },
        }
        statement_paths(&stmt.node, &stmt.span, names, unaliased, holes_of, root_at, found);
        statement_blocks(&stmt.node, names, unaliased, holes_of, root_at, found);
    }
}

fn statement_paths(stmt: &Stmt, span: &Span, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, root_at: &impl Fn(&str) -> i64, found: &mut Walked) {
    match stmt {
        Stmt::Let { value, .. } => expression_paths(value, span, names, unaliased, holes_of, root_at, found),
        Stmt::Comptime { value, .. } => expression_paths(value, span, names, unaliased, holes_of, root_at, found),
        Stmt::Assign { target, value, .. } => {
            expression_paths(target, span, names, unaliased, holes_of, root_at, found);
            expression_paths(value, span, names, unaliased, holes_of, root_at, found);
        },
        Stmt::For { iter, .. } => expression_paths(iter, span, names, unaliased, holes_of, root_at, found),
        Stmt::While { cond, .. } => expression_paths(cond, span, names, unaliased, holes_of, root_at, found),
        Stmt::Return(value) => maybe_expression_paths((value).as_ref(), span, names, unaliased, holes_of, root_at, found),
        Stmt::Expr(value) => expression_paths(value, span, names, unaliased, holes_of, root_at, found),
        _ => { },
    }
}

fn maybe_expression_paths(expr: Option<&Expr>, span: &Span, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, root_at: &impl Fn(&str) -> i64, found: &mut Walked) { expression_paths(match expr { Some(__nikaia_value) => __nikaia_value, None => return }, span, names, unaliased, holes_of, root_at, found); }

fn expression_paths(expr: &Expr, span: &Span, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, root_at: &impl Fn(&str) -> i64, found: &mut Walked) {
    for hole in holes_of(expr) { expression_paths(&hole, span, names, unaliased, holes_of, root_at, found); }
    match expr {
        Expr::Path(segments) => { if (segments.len() as i64) > 0 { found.seen.push(named_at(path_name(segments, names, unaliased), span)); } },
        Expr::Variable(name) => {
            let name = *name;
            if found.with_names { found.seen.push(Seen::Name(names.resolve(name).to_owned())); }
        },
        Expr::Spawn { .. } => found.seen.push(Seen::Spawn),
        Expr::Dsl { .. } => found.seen.push(Seen::Opaque),
        Expr::Call { func, args, config } => {
            let func = nikaia_std::boxed::open(func);
            a_named_call(func, args, span, names, root_at, found);
            expression_paths(func, span, names, unaliased, holes_of, root_at, found);
            for arg in args.iter() { expression_paths(arg, span, names, unaliased, holes_of, root_at, found); }
            for setting in config.iter() { expression_paths(&setting.value, span, names, unaliased, holes_of, root_at, found); }
        },
        Expr::MethodCall { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            expression_paths(receiver, span, names, unaliased, holes_of, root_at, found);
            for arg in args.iter() { expression_paths(arg, span, names, unaliased, holes_of, root_at, found); }
            for setting in config.iter() { expression_paths(&setting.value, span, names, unaliased, holes_of, root_at, found); }
        },
        Expr::SafeMethod { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            expression_paths(receiver, span, names, unaliased, holes_of, root_at, found);
            for arg in args.iter() { expression_paths(arg, span, names, unaliased, holes_of, root_at, found); }
            for setting in config.iter() { expression_paths(&setting.value, span, names, unaliased, holes_of, root_at, found); }
        },
        Expr::Binary { lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            expression_paths(lhs, span, names, unaliased, holes_of, root_at, found);
            expression_paths(rhs, span, names, unaliased, holes_of, root_at, found);
        },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); expression_paths(expr, span, names, unaliased, holes_of, root_at, found) },
        Expr::Try(inner) => { let inner = nikaia_std::boxed::open(inner); expression_paths(inner, span, names, unaliased, holes_of, root_at, found) },
        Expr::Throw(inner) => { let inner = nikaia_std::boxed::open(inner); expression_paths(inner, span, names, unaliased, holes_of, root_at, found) },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); expression_paths(expr, span, names, unaliased, holes_of, root_at, found) },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); expression_paths(base, span, names, unaliased, holes_of, root_at, found) },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); expression_paths(base, span, names, unaliased, holes_of, root_at, found) },
        Expr::Index { base, index } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            expression_paths(base, span, names, unaliased, holes_of, root_at, found);
            expression_paths(index, span, names, unaliased, holes_of, root_at, found);
        },
        Expr::Range { start, end, .. } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end);
            expression_paths(start, span, names, unaliased, holes_of, root_at, found);
            expression_paths(end, span, names, unaliased, holes_of, root_at, found);
        },
        Expr::Tuple(parts) => { for part in parts.iter() { expression_paths(part, span, names, unaliased, holes_of, root_at, found); } },
        Expr::Coalesce { value, fallback } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            expression_paths(value, span, names, unaliased, holes_of, root_at, found);
            expression_paths(fallback, span, names, unaliased, holes_of, root_at, found);
        },
        Expr::TryCatch { expr, .. } => { let expr = nikaia_std::boxed::open(expr); expression_paths(expr, span, names, unaliased, holes_of, root_at, found) },
        Expr::If { cond, .. } => { let cond = nikaia_std::boxed::open(cond); expression_paths(cond, span, names, unaliased, holes_of, root_at, found) },
        Expr::Match { value, arms } => {
            let value = nikaia_std::boxed::open(value);
            expression_paths(value, span, names, unaliased, holes_of, root_at, found);
            for arm in arms.iter() {
                maybe_expression_paths((arm.guard).as_ref(), span, names, unaliased, holes_of, root_at, found);
                expression_paths(&arm.body, span, names, unaliased, holes_of, root_at, found);
            }
        },
        Expr::StructLit { fields, .. } => { for field in fields.iter() { maybe_expression_paths((field.value).as_ref(), span, names, unaliased, holes_of, root_at, found); } },
        Expr::ListLit { items, .. } => { for item in items.iter() { expression_paths(item, span, names, unaliased, holes_of, root_at, found); } },
        Expr::With { base, fields, .. } => {
            let base = nikaia_std::boxed::open(base);
            expression_paths(base, span, names, unaliased, holes_of, root_at, found);
            for field in fields.iter() { maybe_expression_paths((field.value).as_ref(), span, names, unaliased, holes_of, root_at, found); }
        },
        Expr::Return(value) => { let value = nikaia_std::boxed::open(value); maybe_expression_paths((value).as_ref(), span, names, unaliased, holes_of, root_at, found) },
        Expr::Select(arms) => { for arm in arms.iter() { expression_paths(&arm.value, span, names, unaliased, holes_of, root_at, found); } },
        _ => { },
    }
}

fn statement_blocks(stmt: &Stmt, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, root_at: &impl Fn(&str) -> i64, found: &mut Walked) {
    match stmt {
        Stmt::For { body, .. } => block_names(body, names, unaliased, holes_of, root_at, found),
        Stmt::While { body, .. } => block_names(body, names, unaliased, holes_of, root_at, found),
        Stmt::Let { value, .. } => expression_blocks(value, names, unaliased, holes_of, root_at, found),
        Stmt::Comptime { value, .. } => expression_blocks(value, names, unaliased, holes_of, root_at, found),
        Stmt::Expr(value) => expression_blocks(value, names, unaliased, holes_of, root_at, found),
        Stmt::Assign { target, value, .. } => {
            expression_blocks(target, names, unaliased, holes_of, root_at, found);
            expression_blocks(value, names, unaliased, holes_of, root_at, found);
        },
        Stmt::Return(value) => { expression_blocks(match value { Some(__nikaia_value) => __nikaia_value, None => return }, names, unaliased, holes_of, root_at, found); },
        _ => { },
    }
}

fn expression_blocks(expr: &Expr, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, root_at: &impl Fn(&str) -> i64, found: &mut Walked) {
    match expr {
        Expr::Block(block) => block_names(block, names, unaliased, holes_of, root_at, found),
        Expr::Unsafe(block) => block_names(block, names, unaliased, holes_of, root_at, found),
        Expr::Overlap(block) => block_names(block, names, unaliased, holes_of, root_at, found),
        Expr::Closure { body, .. } => block_names(body, names, unaliased, holes_of, root_at, found),
        Expr::Call { func, args, config } => {
            let func = nikaia_std::boxed::open(func);
            expression_blocks(func, names, unaliased, holes_of, root_at, found);
            for arg in args.iter() { expression_blocks(arg, names, unaliased, holes_of, root_at, found); }
            for setting in config.iter() { expression_blocks(&setting.value, names, unaliased, holes_of, root_at, found); }
        },
        Expr::MethodCall { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            expression_blocks(receiver, names, unaliased, holes_of, root_at, found);
            for arg in args.iter() { expression_blocks(arg, names, unaliased, holes_of, root_at, found); }
            for setting in config.iter() { expression_blocks(&setting.value, names, unaliased, holes_of, root_at, found); }
        },
        Expr::SafeMethod { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            expression_blocks(receiver, names, unaliased, holes_of, root_at, found);
            for arg in args.iter() { expression_blocks(arg, names, unaliased, holes_of, root_at, found); }
            for setting in config.iter() { expression_blocks(&setting.value, names, unaliased, holes_of, root_at, found); }
        },
        Expr::If { then_branch, else_branch, .. } => {
            block_names(then_branch, names, unaliased, holes_of, root_at, found);
            block_names(match else_branch { Some(__nikaia_value) => __nikaia_value, None => return }, names, unaliased, holes_of, root_at, found);
        },
        Expr::TryCatch { expr, handler } => {
            let expr = nikaia_std::boxed::open(expr);
            expression_blocks(expr, names, unaliased, holes_of, root_at, found);
            block_names(handler, names, unaliased, holes_of, root_at, found);
        },
        Expr::Match { arms, .. } => { for arm in arms.iter() { expression_blocks(&arm.body, names, unaliased, holes_of, root_at, found); } },
        Expr::Select(arms) => { for arm in arms.iter() { block_names(&arm.body, names, unaliased, holes_of, root_at, found); } },
        _ => { },
    }
}

fn path_name(segments: &Vec<winnow_grammar::Symbol>, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String) -> String {
    let mut name = unaliased(names.resolve(*nikaia_std::index::get(&segments, 0)));
    for k in 1..segments.len() as i64 {
        let segment = names.resolve(*nikaia_std::index::get(&segments, nikaia_std::index::at(k)));
        name = format!("{}::{}", name, segment);
    }
    name
}

fn named_at(name: String, span: &Span) -> Seen { Seen::Path { name, span: span.clone() } }

fn a_named_call(func: &Expr, args: &Vec<Expr>, span: &Span, names: &winnow_grammar::InternerContext, root_at: &impl Fn(&str) -> i64, found: &mut Walked) {
    let name = match func {
        Expr::Variable(name) => { let name = *name; names.resolve(name).to_owned() },
        Expr::Path(segments) => written_path(names, segments),
        _ => String::from(""),
    };
    if (name.len() as i64) == 0 {
        found.seen.push(Seen::Opaque);
        return;
    }
    let at = root_at(&name);
    let mut wrote: Option<Wrote> = None;
    if at >= 0 && at < args.len() as i64 { wrote = written_root(names, nikaia_std::index::get(&args, nikaia_std::index::at(at))); }
    found.seen.push(Seen::Call { name, wrote, span: span.clone() });
}


// --- http1.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Field<'a> {
    pub name: &'a str,
    pub value: &'a str,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Line<'a> {
    Field(Field<'a>),
    Skip,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Written<'a> {
    pub words: Vec<&'a str>,
    pub fields: Vec<Field<'a>>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Header<'a> {
    pub name: String,
    pub value: &'a str,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Read<'a> {
    pub refused: &'a str,
    pub method: &'a str,
    pub target: &'a str,
    pub length: i64,
    pub keep_alive: bool,
    pub headers: Vec<Header<'a>>,
}

grammar! {
    grammar Http1 {

        rule WS =
            ""
            -> { }

        pub rule head -> Written<'a> =
            words:__nikaia_list<&'a str>(item = WORD, sep = " ") "\r\n" lines:line* "\r\n" eof
            -> { Written { words, fields: fields(lines) } }

        rule WORD -> &'a str =
            w:text(WORD_PIECE*)
            -> { w }

        rule WORD_PIECE =
            not(" ") not("\r\n") any
            -> { }

        rule line -> Line<'a> =
            n:text(NAME_PIECE*) ":" v:text(REST_PIECE*) "\r\n"
            -> { Line::Field(Field { name: n, value: v }) }
          | OTHER "\r\n"
            -> { Line::Skip }

        rule NAME_PIECE =
            not(":") not("\r\n") any
            -> { }

        rule REST_PIECE =
            not("\r\n") any
            -> { }

        rule OTHER =
            REST_PIECE+
            -> { }

        rule __nikaia_list<T>(item: Rule<T>, sep) -> Vec<T> =
          first:item rest:__nikaia_list_more<T>(item = item, sep = sep)*
            -> { let mut all = vec![first]; all.extend(rest); all }
        | ""
            -> { Vec::new() }

        rule __nikaia_list_more<T>(item: Rule<T>, sep) -> T =
          sep x:item
            -> { x }
    }
}

fn fields(lines: Vec<Line<'_>>) -> Vec<Field<'_>> {
    let mut all = Vec::new();
    for line in lines.into_iter() {
        match line {
            Line::Field(f) => { all.push(f); },
            Line::Skip => { },
        }
    }
    all
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn read_head<'a>(written: &Written<'a>) -> Read<'a> {
    if (written.words.len() as i64) < 3 { return refused("400 a request line that is not three words"); }
    let method = *nikaia_std::index::get(&written.words, 0);
    let target = *nikaia_std::index::get(&written.words, 1);
    if !(*nikaia_std::index::get(&written.words, 2)).starts_with("HTTP/1.") { return refused("400 a version this does not speak"); }
    if method != "GET" && method != "POST" { return refused("400 a method this does not answer"); }
    let mut length: i64 = 0;
    let mut keep_alive = false;
    let mut headers: Vec<Header<'_>> = vec![];
    for field in written.fields.iter() {
        let name = field.name.trim().to_lowercase();
        let value = field.value.trim();
        if name == "content-length" {
            let n = nikaia_std::index::or(text::parse_i64(value), || -1);
            if n < 0 { return refused("400 a content-length that is not a count"); }
            length = n;
        } else if name == "connection" { keep_alive = value.to_lowercase() == "keep-alive"; } else if name == "transfer-encoding" { return refused("400 a transfer-encoding this does not speak"); }
        headers.push(Header { name, value });
    }
    Read { refused: "", method, target, length, keep_alive, headers }
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn refused(why: &str) -> Read<'_> { Read { refused: why, method: "", target: "", length: 0, keep_alive: false, headers: vec![] } }


// --- ledger.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum LedgerLine<'a> {
    Table { kind: &'a str, name: &'a str },
    Sources,
    Pair { key: &'a str, value: &'a str },
    Nothing,
    Unterminated,
    Bad(&'a str),
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Refused {
    Because(String),
}

impl Refused {
    fn message(&self) -> String {
        match self {
            Refused::Because(why) => why.to_owned(),
        }
    }
}
impl std::fmt::Display for Refused {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.message())
    }
}
impl std::error::Error for Refused {}

grammar! {
    grammar LedgerText {

        rule WS =
            ""
            -> { }

        pub rule file -> Vec<LedgerLine<'a>> =
            ls:line* last:BODY eof
            -> {
                let mut all = Vec::new();
                for l in ls.into_iter() { all.push(l); }
                all.push(last);
                all
            }

        rule line -> LedgerLine<'a> =
            l:BODY line_ending
            -> { l }

        rule BODY -> LedgerLine<'a> =
            SP l:AFTER
            -> { l }

        rule AFTER -> LedgerLine<'a> =
            "#" REST
            -> { LedgerLine::Nothing }
          | "[" t:TABLE
            -> { t }
          | peek(END)
            -> { LedgerLine::Nothing }
          | k:text(KEY) "=" v:text(REST)
            -> { LedgerLine::Pair { key: k.trim(), value: v.trim() } }
          | r:text(REST)
            -> { LedgerLine::Bad(r.trim()) }

        rule TABLE -> LedgerLine<'a> =
            "sources]" SP peek(END)
            -> { LedgerLine::Sources }
          | k:KIND ".\"" n:text(NAME) CLOSE
            -> { LedgerLine::Table { kind: k, name: n } }
          | KIND ".\"" REST
            -> { LedgerLine::Unterminated }

        rule KIND -> &'a str =
            "fn"
            -> { "fn" }
          | "type"
            -> { "type" }
          | "trait"
            -> { "trait" }
          | "impl"
            -> { "impl" }

        rule SP =
            SPACE*
            -> { }

        rule SPACE =
            " "
            -> { }
          | "\t"
            -> { }

        rule END =
            line_ending
            -> { }
          | eof
            -> { }

        rule REST =
            until(line_ending | eof)
            -> { }

        rule CLOSE =
            "\"]" SP peek(END)
            -> { }

        rule NAME =
            until("\"]" | line_ending | eof)
            -> { }

        rule KEY =
            until("=" | line_ending | eof)
            -> { }
    }
}

grammar! {
    grammar LedgerValue {

        pub rule list -> Vec<&'a str> =
            "[" items:__nikaia_list<&'a str>(item = QUOTED, sep = ",") TRAILING "]" eof
            -> { items }

        rule TRAILING =
            ","
            -> { }
          | empty
            -> { }

        rule QUOTED -> &'a str =
            "\"" s:text(INSIDE) "\""
            -> { s }

        rule INSIDE =
            PIECE*
            -> { }

        rule PIECE =
            ESCAPED
            -> { }
          | not("\"") not("\\") any
            -> { }

        rule ESCAPED =
            "\\" any
            -> { }

        rule __nikaia_list<T>(item: Rule<T>, sep) -> Vec<T> =
          first:item rest:__nikaia_list_more<T>(item = item, sep = sep)*
            -> { let mut all = vec![first]; all.extend(rest); all }
        | ""
            -> { Vec::new() }

        rule __nikaia_list_more<T>(item: Rule<T>, sep) -> T =
          sep x:item
            -> { x }
    }
}

pub fn unquote(value: &str) -> Result<String, nikaia_std::error::Thrown<Refused>> {
    Ok(unquote_at(value, "")?)
}

fn unquote_at(value: &str, at: &str) -> Result<String, nikaia_std::error::Thrown<Refused>> {
    if (value.len() as i64) < 2 || !value.starts_with("\"") || !value.ends_with("\"") { return Err(nikaia_std::error::throwing(Refused::Because(format!("{}expected a quoted string, found `{}`", at, value)), &"unquote_at")); }
    Ok(unescaped(nikaia_std::index::get(&value, nikaia_std::index::at(1..value.len() as i64 - 1))))
}

pub fn list(value: &str) -> Result<Vec<String>, nikaia_std::error::Thrown<Refused>> {
    Ok(list_at(value, "")?)
}

fn list_at(value: &str, at: &str) -> Result<Vec<String>, nikaia_std::error::Thrown<Refused>> {
    if value == "[]" { return Ok(vec![]); }
    let entries = match nikaia_std::grammar::parse(&*value, LedgerValue::parse_list()) {
        Ok(value) => value,
        Err(_error) => { return Err(nikaia_std::error::throwing(Refused::Because(format!("{}expected a list, found `{}`", at, value)), &"list_at")) },
    };
    let mut out: Vec<String> = vec![];
    for entry in entries.iter() {
        let entry = *entry;
        out.push(unescaped(entry));
    }
    Ok(out)
}

fn unescaped(inside: &str) -> String {
    if !inside.contains("\\") { return inside.to_owned(); }
    let mut out: String = String::from("");
    let mut escaped = false;
    for c in inside.chars() {
        if escaped {
            if c == 'n' { out.push('\n'); } else { out.push(c); }
            escaped = false;
        } else if c == '\\' { escaped = true; } else { out.push(c); }
    }
    out
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Section {
    Header,
    Function,
    Kind,
    Sources,
    Nothing,
}

pub fn read(written: &str) -> Result<Ledger, nikaia_std::error::Thrown<Refused>> {
    let mut ledger = Ledger::blank();
    let mut section = Section::Header;
    let mut current: String = String::from("");
    let mut function = FnContract::empty();
    let mut a_type = TypeContract::empty();
    let mut traits: Vec<String> = vec![];
    let mut functions: Vec<String> = vec![];
    let mut answers: Vec<(String, String)> = vec![];
    let lines = match nikaia_std::grammar::parse(&*written, LedgerText::parse_file()) {
        Ok(value) => value,
        Err(error) => { return Err(nikaia_std::error::throwing(Refused::Because(format!("{}", error)), &"read")) },
    };
    let mut n: i64 = 0;
    for one in lines.iter() {
        n += 1;
        match one {
            LedgerLine::Table { kind, name } => {
                let kind = *kind; let name = *name;
                if section == Section::Function {
                    ledger.functions.insert(current.to_owned(), function);
                    function = FnContract::empty();
                }
                if section == Section::Kind {
                    ledger.types.insert(current.to_owned(), a_type);
                    a_type = TypeContract::empty();
                }
                current = name.to_owned();
                if kind == "fn" {
                    if ledger.functions.contains_key(&current) {
                        function = nikaia_std::index::or(match *nikaia_std::index::get(&ledger.functions, &current) {
                            Some(__nikaia_it) => Some(__nikaia_it.clone()),
                            None => None,
                        }, || FnContract::empty());
                    }
                    functions.push(current.to_owned());
                    section = Section::Function;
                } else if kind == "type" {
                    if ledger.types.contains_key(&current) {
                        a_type = nikaia_std::index::or(match *nikaia_std::index::get(&ledger.types, &current) {
                            Some(__nikaia_it) => Some(__nikaia_it.clone()),
                            None => None,
                        }, || TypeContract::empty());
                    }
                    section = Section::Kind;
                } else if kind == "trait" {
                    if !ledger.traits.contains_key(&current) { ledger.traits.insert(current.to_owned(), collections::BTreeSet::new()); }
                    traits.push(current.to_owned());
                    section = Section::Nothing;
                } else {
                    answers.push(implemented(&current, n)?);
                    section = Section::Nothing;
                }
            },
            LedgerLine::Sources => {
                if section == Section::Function {
                    ledger.functions.insert(current.to_owned(), function);
                    function = FnContract::empty();
                }
                if section == Section::Kind {
                    ledger.types.insert(current.to_owned(), a_type);
                    a_type = TypeContract::empty();
                }
                section = Section::Sources;
            },
            LedgerLine::Pair { key, value } => {
                let key = *key; let value = *value;
                if section == Section::Header { header(&mut ledger, key, value, n)?; } else if section == Section::Sources { ledger.sources.insert(unquoted(key, n)?, unquoted(value, n)?); } else if section == Section::Function { function_key(&mut function, &current, key, value, n)?; } else if section == Section::Kind { type_key(&mut a_type, key, value, n)?; } else { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: a `trait` or an `impl` table has no keys, and this has `{}`", n, key)), &"read")); }
            },
            LedgerLine::Unterminated => { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: unterminated section header", n)), &"read")); },
            LedgerLine::Bad(text) => {
                let text = *text;
                return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: not a key and a value: {}", n, text)), &"read"));
            },
            LedgerLine::Nothing => { },
        }
    }
    if section == Section::Function { ledger.functions.insert(current.to_owned(), function); }
    if section == Section::Kind { ledger.types.insert(current.to_owned(), a_type); }
    for name in traits.iter() {
        let prefix = format!("{}::", name);
        let mut methods: collections::BTreeSet<String> = collections::BTreeSet::new();
        for entry in functions.iter() {
            let method = after_prefix(entry, &prefix);
            if method.is_some() {
                let rest = nikaia_std::index::or(method, || "".into());
                if !rest.contains("::") { methods.insert(rest.to_owned()); }
            }
        }
        ledger.traits.insert(name.to_owned(), methods);
    }
    let mut done: Vec<String> = vec![];
    for (trait_name, _) in answers.iter() {
        if !nikaia_std::list::contains(&done, trait_name) {
            let mut types: collections::BTreeSet<String> = collections::BTreeSet::new();
            for (other, answering) in answers.iter() { if other == trait_name { types.insert(answering.to_owned()); } }
            ledger.implementations.insert(trait_name.to_owned(), types);
            done.push(trait_name.to_owned());
        }
    }
    Ok(ledger)
}

fn header(ledger: &mut Ledger, key: &str, value: &str, n: i64) -> Result<(), nikaia_std::error::Thrown<Refused>> {
    if key == "version" {
        let number = nikaia_std::index::or(text::parse_i64(value), || -1);
        if number < 0 { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: `version` is a whole number, not `{}`", n, value)), &"header")); }
        if number > 4294967295i64 { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: `version` is a whole number, not `{}`", n, value)), &"header")); }
        ledger.version = u32::try_from(number).unwrap_or_else(|_| panic!("the value does not fit in an `u32`"));
    } else if key == "toolchain" { ledger.toolchain = unquoted(value, n)?; } else if key == "inference" { ledger.inference = unquoted(value, n)?; } else { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: unknown header key `{}`", n, key)), &"header")); }
    Ok(())
}

fn implemented(name: &str, n: i64) -> Result<(String, String), nikaia_std::error::Thrown<Refused>> {
    let c: Vec<char> = nikaia_std::list::chars(name.chars());
    let at = find_text(&c, 0, " for ");
    if at < 0 { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: an `impl` entry is `A for T`: {}", n, name)), &"implemented")); }
    Ok((trimmed(&slice(&c, 0, at)), trimmed(&slice(&c, at + 5, c.len() as i64))))
}

fn function_key(entry: &mut FnContract, name: &str, key: &str, value: &str, n: i64) -> Result<(), nikaia_std::error::Thrown<Refused>> {
    if key == "pub" { entry.public = value == "true"; } else if key == "sync" { entry.sync_claim = sync_of(value, n)?; } else if key == "throws" { entry.fails_with = throws_of(value, n)?; } else if key == "returns" { entry.borrows = borrows_of(&unquoted(value, n)?, n)?; } else if key == "signature" {
        let spelled = spelled_signature(&unquoted(value, n)?, name)?;
        if spelled.mutates { entry.mutates = true; }
        if (spelled.borrows.len() as i64) > 0 { entry.borrows = spelled.borrows.to_owned(); }
        entry.signature = Some(spelled.signature);
    } else if key == "keeps" { entry.keeps = entries(value, n)?; } else if key == "mutates" { entry.mutates = value == "true"; } else if key == "locks" {
        let said = value.trim();
        if said == "true" { entry.touches_a_lock = Lock::Holds; } else if said == "\"?\"" { entry.touches_a_lock = Lock::Undecided; } else { entry.touches_a_lock = Lock::No; }
    } else if key == "threads" {
        let said = value.trim();
        if said == "true" { entry.threads = Threads::May; } else if said == "false" { entry.threads = Threads::MayNot; } else { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: `threads` is `true` or `false`, not `{}`. (Leave it out if nobody knows.)", n, said)), &"function_key")); }
    } else if key == "touches" {
        let mut touches: Vec<Touch> = vec![];
        for one in entries(value, n)? { touches.push(touch_of(&one)?); }
        entry.touches = touches;
        entry.touches_known = true;
    } else if key == "provenance" { entry.provenance = Some(provenance_of(&unquoted(value, n)?, n)?); } else if key == "views" {
        let mut views: Vec<Held> = vec![];
        for held in entries(value, n)? {
            let read = held_of(&held);
            if read.is_none() { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: a tether state is `name: borrowed` or `name: tethered`, not `{}`", n, held)), &"function_key")); }
            views.push(nikaia_std::index::or(read, || Held { position: String::from(""), state: State::Borrowed }));
        }
        entry.views = views;
    } else if key == "sharing" {
        let mut classes: Vec<Class> = vec![];
        for class in entries(value, n)? {
            let read = class_of(&class);
            if read.is_none() { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: a sharing class is `a | b: plain` or `a | b: atomic`, not `{}`", n, class)), &"function_key")); }
            classes.push(nikaia_std::index::or(read, || Class { members: vec![], count: Count::Atomic }));
        }
        entry.sharing = classes;
    } else if key == "ends_by_length" { entry.ends_by_length = value == "true"; } else { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: unknown key `{}` on a fn", n, key)), &"function_key")); }
    Ok(())
}

fn type_key(entry: &mut TypeContract, key: &str, value: &str, n: i64) -> Result<(), nikaia_std::error::Thrown<Refused>> {
    if key == "pub" { entry.public = value == "true"; } else if key == "crosses" { if value == "true" { entry.crosses = Crosses::May; } else if value == "false" { entry.crosses = Crosses::MayNot; } else { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: `crosses` is `true` or `false`, not `{}` - and leaving the line out is the third answer", n, value)), &"type_key")); } } else if key == "compares" { entry.compares = value.trim() == "true"; } else if key == "copies" { entry.copies = value.trim() == "true"; } else if key == "tethered" { entry.tethered = entries(value, n)?; } else if key == "touches" { entry.touches = entries(value, n)?; } else if key == "iterates" {
        let said = unquoted(value, n)?;
        if said != "throws" { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: `iterates` is `throws` and nothing else, not `{}` - a step that cannot fail says nothing", n, said)), &"type_key")); }
        entry.iterates_fallibly = true;
    } else if key == "variants" {
        let mut variants: Vec<VariantContract> = vec![];
        for one in entries(value, n)? { variants.push(variant_of(&one)); }
        entry.variants = variants;
    } else if key == "fields" {
        let mut fields: Vec<FieldContract> = vec![];
        for one in entries(value, n)? { fields.push(field_of(&one)); }
        entry.fields = fields;
    } else { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: unknown key `{}` on a type", n, key)), &"type_key")); }
    Ok(())
}

fn unquoted(value: &str, n: i64) -> Result<String, nikaia_std::error::Thrown<Refused>> {
    Ok(unquote_at(value, &format!("line {}: ", n))?)
}

fn entries(value: &str, n: i64) -> Result<Vec<String>, nikaia_std::error::Thrown<Refused>> {
    Ok(list_at(value, &format!("line {}: ", n))?)
}

fn sync_of(value: &str, n: i64) -> Result<Sync, nikaia_std::error::Thrown<Refused>> {
    if value == "true" { return Ok(Sync::Asserted); }
    if value == "false" { return Ok(Sync::No); }
    if value == "\"inferred\"" { return Ok(Sync::Inferred); }
    let c: Vec<char> = nikaia_std::list::chars(value.chars());
    if value.ends_with(")\"") && (value.starts_with("\"sync(") || value.starts_with("\"from(")) && (c.len() as i64) >= 8 {
        let inside = slice(&c, 6, c.len() as i64 - 2);
        let name = inside.trim();
        if (name.len() as i64) > 0 { return Ok(Sync::From(name.to_owned())); }
    }
    return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: `sync` is `true` (the source says so), `\"inferred\"` (the body implies it) or `\"sync(f)\"` (its lambda decides), not `{}`", n, value)), &"sync_of"))
}

fn throws_of(value: &str, n: i64) -> Result<Vec<String>, nikaia_std::error::Thrown<Refused>> {
    if value == "true" {
        let unnamed: String = String::from("?");
        return Ok(vec![unnamed]);
    }
    Ok(entries(value, n)?)
}

fn borrows_of(value: &str, n: i64) -> Result<Vec<String>, nikaia_std::error::Thrown<Refused>> {
    let c: Vec<char> = nikaia_std::list::chars(value.chars());
    let mut from: i64 = -1;
    if value.ends_with(")") { if value.starts_with("ref(") { from = 4; } else if value.starts_with("borrows(") { from = 8; } }
    if from < 0 { return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: expected `ref(…)`, found `{}`", n, value)), &"borrows_of")); }
    let inside = slice(&c, from, c.len() as i64 - 1);
    let mut names: Vec<String> = vec![];
    for part in inside.split("|") {
        let name = part.trim();
        if (name.len() as i64) > 0 { names.push(name.to_owned()); }
    }
    Ok(names)
}

fn provenance_of(value: &str, n: i64) -> Result<Provenance, nikaia_std::error::Thrown<Refused>> {
    if value == "trusted" { return Ok(Provenance::Trusted); }
    if value == "untrusted" { return Ok(Provenance::Untrusted); }
    return Err(nikaia_std::error::throwing(Refused::Because(format!("line {}: a provenance is `trusted` or `untrusted`, not `{}`", n, value)), &"provenance_of"))
}

pub fn touch_of(written: &str) -> Result<Touch, nikaia_std::error::Thrown<Refused>> {
    let __keep_frame = nikaia_std::tether::Keep::new();
    let whole = written.trim();
    let c: Vec<char> = nikaia_std::list::chars(whole.chars());
    let space = find_last(&c, ' ');
    if space < 0 { return Err(nikaia_std::error::throwing(Refused::Because(format!("a touch is `resource read` or `resource write`, found `{}`", whole)), &"touch_of")); }
    let said = slice(&c, space + 1, c.len() as i64);
    let access = said.trim();
    let mut write = false;
    if access == "write" { write = true; } else if access != "read" { return Err(nikaia_std::error::throwing(Refused::Because(format!("a touch is `read` or `write`, not `{}` (in `{}`)", access, whole)), &"touch_of")); }
    let before = slice(&c, 0, space);
    let resource = before.trim();
    let r: Vec<char> = nikaia_std::list::chars(resource.chars());
    let open = find(&r, 0, '(');
    let mut kind: String = resource.to_owned();
    let mut parameter: Option<String> = None;
    if open >= 0 {
        if !resource.ends_with(")") { return Err(nikaia_std::error::throwing(Refused::Because(format!("a resource is `kind(parameter)`, and `{}` has no `)`", resource)), &"touch_of")); }
        let named = __keep_frame.put(slice(&r, 0, open));
        kind = named.trim().to_owned();
        let inside = __keep_frame.put(slice(&r, open + 1, r.len() as i64 - 1));
        parameter = Some(inside.trim().to_owned());
    }
    if (kind.len() as i64) == 0 { return Err(nikaia_std::error::throwing(Refused::Because(format!("a touch needs a resource kind, found `{}`", whole)), &"touch_of")); }
    Ok(Touch { kind, parameter, write })
}

pub fn held_of(written: &str) -> Option<Held> {
    let c: Vec<char> = nikaia_std::list::chars(written.chars());
    let colon = find_last(&c, ':');
    if colon < 0 { return None; }
    let state = State::parse(&slice(&c, colon + 1, c.len() as i64));
    if state.is_none() { return None; }
    let position = slice(&c, 0, colon);
    Some(Held { position: position.trim().to_owned(), state: nikaia_std::index::or(state, || State::Borrowed) })
}

pub fn class_of(written: &str) -> Option<Class> {
    let c: Vec<char> = nikaia_std::list::chars(written.chars());
    let colon = find_last(&c, ':');
    if colon < 0 { return None; }
    let named = slice(&c, 0, colon);
    let mut members: Vec<String> = vec![];
    for part in named.split("|") {
        let member = part.trim();
        if (member.len() as i64) > 0 { members.push(member.to_owned()); }
    }
    if (members.len() as i64) == 0 { return None; }
    let count = Count::parse(&slice(&c, colon + 1, c.len() as i64));
    if count.is_none() { return None; }
    Some(Class { members, count: nikaia_std::index::or(count, || Count::Atomic) })
}

pub fn variant_of(written: &str) -> VariantContract {
    let __keep_frame = nikaia_std::tether::Keep::new();
    let whole = written.trim();
    let c: Vec<char> = nikaia_std::list::chars(whole.chars());
    let paren = find(&c, 0, '(');
    if paren >= 0 {
        let named = slice(&c, 0, paren);
        let rest = slice(&c, paren + 1, c.len() as i64);
        let inside = without_last(rest.trim_end(), ')');
        let mut holds: Vec<FieldContract> = vec![];
        let mut at = 0;
        for part in split_args(&inside) {
            holds.push(FieldContract { name: format!("{}", at), ty: parse(&part), public: true });
            at += 1;
        }
        return VariantContract { name: named.trim().to_owned(), holds, positional: true };
    }
    let brace = find(&c, 0, '{');
    if brace >= 0 {
        let named = slice(&c, 0, brace);
        let rest = slice(&c, brace + 1, c.len() as i64);
        let inside = without_last(rest.trim_end(), '}');
        let mut holds: Vec<FieldContract> = vec![];
        for part in split_args(&inside) {
            let p: Vec<char> = nikaia_std::list::chars(part.chars());
            let colon = find(&p, 0, ':');
            if colon >= 0 {
                let field = __keep_frame.put(slice(&p, 0, colon));
                holds.push(FieldContract { name: field.trim().to_owned(), ty: parse(&slice(&p, colon + 1, p.len() as i64)), public: true });
            }
        }
        return VariantContract { name: named.trim().to_owned(), holds, positional: false };
    }
    let nothing: Vec<FieldContract> = vec![];
    VariantContract { name: whole.to_owned(), holds: nothing, positional: false }
}

fn field_of(written: &str) -> FieldContract {
    let __keep_frame = nikaia_std::tether::Keep::new();
    let mut field: String = written.trim().to_owned();
    let mut public = false;
    if field.starts_with("pub ") {
        public = true;
        let rest = __keep_frame.put(from_char(&field, 4));
        field = rest.trim().to_owned();
    }
    let c: Vec<char> = nikaia_std::list::chars(field.chars());
    let colon = find(&c, 0, ':');
    if colon < 0 { return FieldContract { name: field.to_owned(), ty: Ty::Unknown, public }; }
    let name = slice(&c, 0, colon);
    FieldContract { name: name.trim().to_owned(), ty: parse(&slice(&c, colon + 1, c.len() as i64)), public }
}

pub fn signature_of(written: &str) -> Result<Signature, nikaia_std::error::Thrown<Refused>> {
    let spelled = spelled_signature(written, "")?;
    Ok(spelled.signature)
}

#[derive(Debug, Clone)]
pub struct Spelling {
    pub signature: Signature,
    pub borrows: Vec<String>,
    pub mutates: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum Piece<'a> {
    Owner { view: bool, mutates: bool },
    Typed { ty: &'a str, mutates: bool },
    Named { name: &'a str, ty: &'a str, mutable: bool },
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct Declared<'a> {
    name: &'a str,
    traits: Vec<&'a str>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct Setting<'a> {
    name: &'a str,
    ty: &'a str,
    default: &'a str,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct Signed<'a> {
    declared: Vec<Declared<'a>>,
    parts: Vec<Piece<'a>>,
    settings: Vec<Setting<'a>>,
    result: Option<&'a str>,
}

grammar! {
    grammar SignatureText {

        pub rule signature -> Signed<'a> =
            d:bracket "(" ps:__nikaia_list<Piece<'a>>(item = part, sep = ",") TRAILING ss:settings ")" r:result? eof
            -> { Signed { declared: d, parts: ps, settings: ss, result: r } }

        rule bracket -> Vec<Declared<'a>> =
            "[" ds:__nikaia_list<Declared<'a>>(item = declared, sep = ",") "]"
            -> { ds }
          | empty
            -> { Vec::new() }

        rule declared -> Declared<'a> =
            n:raw_ident COLON ts:__nikaia_list<&'a str>(item = BOUND, sep = "+")
            -> { Declared { name: n, traits: ts } }
          | n:raw_ident
            -> { Declared { name: n, traits: Vec::new() } }

        rule part -> Piece<'a> =
            REF MUT SELF
            -> { Piece::Owner { view: true, mutates: true } }
          | REF SELF
            -> { Piece::Owner { view: true, mutates: false } }
          | MUT SELF COLON t:TYPE
            -> { Piece::Typed { ty: t, mutates: true } }
          | SELF COLON t:TYPE
            -> { Piece::Typed { ty: t, mutates: false } }
          | SELF
            -> { Piece::Owner { view: false, mutates: false } }
          | MUT n:raw_ident COLON t:TYPE
            -> { Piece::Named { name: n, ty: t, mutable: true } }
          | n:raw_ident COLON t:TYPE
            -> { Piece::Named { name: n, ty: t, mutable: false } }
          | t:TYPE
            -> { Piece::Typed { ty: t, mutates: false } }

        rule settings -> Vec<Setting<'a>> =
            ";" ss:__nikaia_list<Setting<'a>>(item = setting, sep = ",") TRAILING
            -> { ss }
          | empty
            -> { Vec::new() }

        rule setting -> Setting<'a> =
            n:raw_ident COLON t:SETTING_TYPE "=" d:DEFAULT
            -> { Setting { name: n, ty: t, default: d } }

        rule result -> &'a str =
            "->" t:REST
            -> { t }

        pub rule pointed -> Vec<Vec<&'a str>> =
            ps:POINTING* eof
            -> { ps }

        rule POINTING -> Vec<&'a str> =
            "ref(" ns:__nikaia_list<&'a str>(item = POINTED_NAME, sep = "|") ")"
            -> { ns }
          | WORD_CHARS
            -> { Vec::new() }
          | any
            -> { Vec::new() }

        rule POINTED_NAME -> &'a str =
            WS0 n:raw_ident WS0
            -> { n }

        rule WS0 =
            " "*
            -> { }

        rule WORD_CHARS =
            WORD_CHAR+
            -> { }

        rule WORD_CHAR =
            alpha1
            -> { }
          | digit
            -> { }
          | "_"
            -> { }
          | "$"
            -> { }

        rule REF =
            "ref" not(WORD_CHAR)
            -> { }

        rule MUT =
            "mut" not(WORD_CHAR)
            -> { }

        rule SELF =
            "self" not(WORD_CHAR)
            -> { }

        rule COLON =
            ":" not(":")
            -> { }

        rule TRAILING =
            ","
            -> { }
          | empty
            -> { }

        rule BOUND -> &'a str =
            t:text(BOUND_RUN)
            -> { t.trim() }

        rule BOUND_RUN =
            BOUND_PIECE+
            -> { }

        rule BOUND_PIECE =
            not("+") not(",") not("]") SPAN
            -> { }

        rule TYPE -> &'a str =
            t:text(TYPE_RUN)
            -> { t.trim() }

        rule TYPE_RUN =
            TYPE_PIECE+
            -> { }

        rule TYPE_PIECE =
            not(",") not(")") not(";") SPAN
            -> { }

        rule SETTING_TYPE -> &'a str =
            t:text(SETTING_RUN)
            -> { t.trim() }

        rule SETTING_RUN =
            SETTING_PIECE+
            -> { }

        rule SETTING_PIECE =
            not("=") not(",") not(")") SPAN
            -> { }

        rule DEFAULT -> &'a str =
            t:text(DEFAULT_RUN)
            -> { t.trim() }

        rule DEFAULT_RUN =
            DEFAULT_PIECE+
            -> { }

        rule DEFAULT_PIECE =
            not(",") not(")") SPAN
            -> { }

        rule REST -> &'a str =
            t:text(REST_RUN)
            -> { t.trim() }

        rule REST_RUN =
            until(eof)
            -> { }

        rule SPAN =
            PARENS
            -> { }
          | BRACKETS
            -> { }
          | STRING
            -> { }
          | any
            -> { }

        rule PARENS =
            "(" IN_PARENS* ")"
            -> { }

        rule IN_PARENS =
            not(")") SPAN
            -> { }

        rule BRACKETS =
            "[" IN_BRACKETS* "]"
            -> { }

        rule IN_BRACKETS =
            not("]") SPAN
            -> { }

        rule STRING =
            "\"" STRING_PIECE* "\""
            -> { }

        rule STRING_PIECE =
            "\\" any
            -> { }
          | not("\"") any
            -> { }

        rule __nikaia_list<T>(item: Rule<T>, sep) -> Vec<T> =
          first:item rest:__nikaia_list_more<T>(item = item, sep = sep)*
            -> { let mut all = vec![first]; all.extend(rest); all }
        | ""
            -> { Vec::new() }

        rule __nikaia_list_more<T>(item: Rule<T>, sep) -> T =
          sep x:item
            -> { x }
    }
}

pub fn spelled_signature(written: &str, key: &str) -> Result<Spelling, nikaia_std::error::Thrown<Refused>> {
    let parts = match nikaia_std::grammar::parse(&*written, SignatureText::parse_signature()) {
        Ok(value) => value,
        Err(_error) => { return Err(nikaia_std::error::throwing(Refused::Because(format!("a signature is `[T](a: A; o: O = v) -> R`, found `{}`", written)), &"spelled_signature")) },
    };
    let mut variables: collections::BTreeSet<String> = collections::BTreeSet::new();
    let mut bounds: Vec<(String, Vec<String>)> = vec![];
    for declared in parts.declared.iter() {
        variables.insert(declared.name.to_owned());
        if (declared.traits.len() as i64) > 0 || (key.len() as i64) == 0 {
            let mut traits: Vec<String> = vec![];
            for one in declared.traits.iter() {
                let one = *one;
                traits.push(one.to_owned());
            }
            bounds.push(a_bound(declared.name, traits));
        }
    }
    let mut params: Vec<(String, Ty)> = vec![];
    let mut changed: Vec<String> = vec![];
    let mut order: Vec<String> = vec![];
    let mut receiver_changes = false;
    let mut first = true;
    for part in parts.parts.iter() {
        match part {
            Piece::Owner { view, mutates } => {
                let mutates = *mutates; let view = *view;
                let owner = nikaia_std::index::or(owner_of(key), || "?".into());
                let written_type = if view { format!("ref {}", owner) } else { owner.to_owned() };
                params.push(a_param("self", typed(&written_type, &variables)));
                if mutates { receiver_changes = true; }
                if first { order.push(a_receiver()); }
            },
            Piece::Typed { ty, mutates } => {
                let mutates = *mutates; let ty = *ty;
                params.push(a_param("self", typed(ty, &variables)));
                if mutates { receiver_changes = true; }
                if first { order.push(a_receiver()); }
            },
            Piece::Named { name, ty, mutable } => {
                let mutable = *mutable; let name = *name; let ty = *ty;
                params.push(a_param(name, typed(ty, &variables)));
                if mutable { changed.push(name.to_owned()); }
                order.push(name.to_owned());
            },
        }
        first = false;
    }
    let mut config: Vec<ConfigContract> = vec![];
    for setting in parts.settings.iter() { config.push(ConfigContract { name: setting.name.to_owned(), ty: typed(setting.ty, &variables), default: setting.default.to_owned() }); }
    let mut result: Option<Ty> = None;
    let mut borrows: Vec<String> = vec![];
    let result_text = nikaia_std::index::or(parts.result, || "");
    if parts.result.is_some() {
        result = Some(typed(result_text, &variables));
        borrows = pointed_into(result_text, &order);
    }
    Ok(Spelling { signature: Signature { bounds, params, mutable: changed, config, result }, borrows, mutates: receiver_changes })
}

fn typed(written: &str, variables: &collections::BTreeSet<String>) -> Ty {
    let ty = parse(written);
    if (variables.len() as i64) == 0 { return ty; }
    ty.parameterise(variables)
}

fn pointed_into(result: &str, order: &Vec<String>) -> Vec<String> {
    if !result.contains("ref(") { return vec![]; }
    let groups = match nikaia_std::grammar::parse(&*result, SignatureText::parse_pointed()) {
        Ok(value) => value,
        Err(_error) => { return vec![]; },
    };
    let mut named: Vec<String> = vec![];
    for group in groups.iter() {
        for name in group.iter() {
            let name = *name;
            if !nikaia_std::list::contains(&named, name) { named.push(name.to_owned()); }
        }
    }
    let mut borrows: Vec<String> = vec![];
    for name in order.iter() { if nikaia_std::list::contains(&named, name) { borrows.push(name.to_owned()); } }
    for name in named.iter() { if !nikaia_std::list::contains(&borrows, name) { borrows.push(name.to_owned()); } }
    borrows
}

fn a_bound(name: &str, traits: Vec<String>) -> (String, Vec<String>) { (name.to_owned(), traits) }

fn a_receiver() -> String {
    let receiver: String = String::from("self");
    receiver
}

fn owner_of(key: &str) -> Option<String> {
    let c: Vec<char> = nikaia_std::list::chars(key.chars());
    let mut last: i64 = -1;
    for at in 0..c.len() as i64 { if at + 1 < c.len() as i64 && *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == ':' && *nikaia_std::index::get(&c, nikaia_std::index::at(at + 1)) == ':' { last = at; } }
    if last < 0 { return None; }
    Some(slice(&c, 0, last))
}

fn find(c: &[char], from: i64, target: char) -> i64 {
    for at in from..c.len() as i64 { if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == target { return at; } }
    -1
}

fn find_last(c: &[char], target: char) -> i64 {
    let mut found: i64 = -1;
    for at in 0..c.len() as i64 { if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == target { found = at; } }
    found
}

fn find_text(c: &[char], from: i64, word: &str) -> i64 {
    let w: Vec<char> = nikaia_std::list::chars(word.chars());
    if (w.len() as i64) == 0 || (c.len() as i64) < w.len() as i64 { return -1; }
    for at in from..c.len() as i64 - w.len() as i64 + 1 {
        let mut same = true;
        for k in 0..w.len() as i64 { if same && *nikaia_std::index::get(&c, nikaia_std::index::at(at + k)) != *nikaia_std::index::get(&w, nikaia_std::index::at(k)) { same = false; } }
        if same { return at; }
    }
    -1
}

fn slice(c: &[char], from: i64, to: i64) -> String {
    let mut out: String = String::from("");
    for k in from..to { out.push(*nikaia_std::index::get(&c, nikaia_std::index::at(k))); }
    out
}

fn from_char(written: &str, front: i64) -> String {
    let c: Vec<char> = nikaia_std::list::chars(written.chars());
    slice(&c, front, c.len() as i64)
}

fn after_prefix(written: &str, prefix: &str) -> Option<String> {
    if !written.starts_with(prefix) { return None; }
    let p: Vec<char> = nikaia_std::list::chars(prefix.chars());
    Some(from_char(written, p.len() as i64))
}

fn without_last(written: &str, last: char) -> String {
    let c: Vec<char> = nikaia_std::list::chars(written.chars());
    let mut end = c.len() as i64;
    while end > 0 && *nikaia_std::index::get(&c, nikaia_std::index::at(end - 1)) == last { end -= 1; }
    slice(&c, 0, end)
}

fn a_param(name: &str, ty: Ty) -> (String, Ty) { (name.to_owned(), ty) }

fn trimmed(written: &str) -> String { written.trim().to_owned() }

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Spelled {
    pub text: String,
    pub borrows_said: bool,
    pub mutates_said: bool,
}

pub fn spell(text: &str, key: &str, borrows: &Vec<String>, mutates: bool) -> Spelled {
    let c: Vec<char> = nikaia_std::list::chars(text.trim().chars());
    let mut declared: Vec<String> = vec![];
    let mut open: i64 = 0;
    if (c.len() as i64) > 0 && *nikaia_std::index::get(&c, 0) == '[' {
        let close = matching(&c, 1, '[', ']');
        if close < 0 { return as_written(text); }
        for entry in split_args(&slice(&c, 1, close)) {
            let entry = trimmed(&entry);
            if (entry.len() as i64) > 0 { declared.push(entry); }
        }
        open = close + 1;
        while open < c.len() as i64 && (*nikaia_std::index::get(&c, nikaia_std::index::at(open))).is_whitespace() { open += 1; }
    }
    if open >= c.len() as i64 || *nikaia_std::index::get(&c, nikaia_std::index::at(open)) != '(' { return as_written(text); }
    let close = matching(&c, open + 1, '(', ')');
    if close < 0 { return as_written(text); }
    let inside: Vec<char> = nikaia_std::list::chars(slice(&c, open + 1, close).chars());
    let mut result = slice(&c, close + 1, c.len() as i64);
    let semicolon = top_level_semicolon(&inside);
    let positional = if semicolon < 0 { slice(&inside, 0, inside.len() as i64) } else { slice(&inside, 0, semicolon) };
    let mut parameters: Vec<String> = vec![];
    for part in split_args(&positional) {
        let part = trimmed(&part);
        if (part.len() as i64) > 0 { parameters.push(part); }
    }
    let mut mutates_said = false;
    let mut written_parameters: Vec<String> = vec![];
    for k in 0..parameters.len() as i64 {
        if k == 0 && !is_named(nikaia_std::index::get(&parameters, 0)) {
            written_parameters.push(receiver(nikaia_std::index::get(&parameters, 0), key, mutates));
            mutates_said = mutates;
        } else { written_parameters.push((*nikaia_std::index::get(&parameters, nikaia_std::index::at(k))).to_owned()); }
    }
    let mut borrows_said = false;
    if (borrows.len() as i64) > 0 && (word_starts(&result, "ref").len() as i64) > 0 {
        let pointed = joined_by(borrows, " | ");
        result = replace_ref(&result, &format!("ref({})", pointed));
        borrows_said = true;
    }
    let mut seen: Vec<String> = vec![];
    for entry in declared.iter() { seen.push(before_colon(entry)); }
    let mut body = joined_by(&written_parameters, ", ");
    if semicolon >= 0 {
        let options = trimmed(&slice(&inside, semicolon + 1, inside.len() as i64));
        body = format!("{}; {}", body, options);
    }
    for variable in variables(&format!("{}{}", body, result)) {
        if !seen.contains(&variable) {
            seen.push(variable.to_owned());
            declared.push(variable.to_owned());
        }
    }
    let mut before: String = String::from("");
    if (declared.len() as i64) > 0 {
        let names = joined_by(&declared, ", ");
        before = format!("[{}]", names);
    }
    Spelled { text: without_dollars(&format!("{}({}){}", before, body, result)), borrows_said, mutates_said }
}

fn as_written(text: &str) -> Spelled { Spelled { text: text.to_owned(), borrows_said: false, mutates_said: false } }

fn receiver(written: &str, key: &str, mutates: bool) -> String {
    let has_owner = owner_of(key).is_some();
    let owner = nikaia_std::index::or(owner_of(key), || "".into());
    let viewed = after_prefix(written, "ref ");
    if viewed.is_some() && has_owner && nikaia_std::index::or(viewed.as_deref(), || "") == owner {
        if mutates { return String::from("ref mut self"); }
        return String::from("ref self");
    }
    if viewed.is_none() && has_owner && written == owner && !mutates { return String::from("self"); }
    if mutates { return format!("mut self: {}", written); }
    format!("self: {}", written)
}

fn is_named(part: &str) -> bool {
    let mut rest = trimmed(part);
    while rest.starts_with("mut ") { rest = from_char(&rest, 4); }
    let c: Vec<char> = nikaia_std::list::chars(rest.chars());
    let mut end: i64 = 0;
    while end < c.len() as i64 && is_word_char(*nikaia_std::index::get(&c, nikaia_std::index::at(end))) { end += 1; }
    if end == 0 || !(is_lower(*nikaia_std::index::get(&c, 0)) || *nikaia_std::index::get(&c, 0) == '_') { return false; }
    let after = trimmed_start(&slice(&c, end, c.len() as i64));
    after.starts_with(":") && !after.starts_with("::")
}

fn matching(c: &[char], from: i64, open: char, close: char) -> i64 {
    let mut depth = 0;
    for at in from..c.len() as i64 {
        if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == open { depth += 1; } else if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == close {
            if depth == 0 { return at; }
            depth -= 1;
        }
    }
    -1
}

fn top_level_semicolon(c: &[char]) -> i64 {
    let mut depth = 0;
    for at in 0..c.len() as i64 { if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '[' || *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '(' { depth += 1; } else if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == ']' || *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == ')' { if depth > 0 { depth -= 1; } } else if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == ';' && depth == 0 { return at; } }
    -1
}

fn word_starts(text: &str, word: &str) -> Vec<i64> {
    let c: Vec<char> = nikaia_std::list::chars(text.chars());
    let w: Vec<char> = nikaia_std::list::chars(word.chars());
    let mut starts: Vec<i64> = vec![];
    let mut at = find_text(&c, 0, word);
    while at >= 0 {
        let free_before = at == 0 || !(is_word_char(*nikaia_std::index::get(&c, nikaia_std::index::at(at - 1))) || *nikaia_std::index::get(&c, nikaia_std::index::at(at - 1)) == '$');
        let blank_after = (at + w.len() as i64) < c.len() as i64 && *nikaia_std::index::get(&c, nikaia_std::index::at(at + w.len() as i64)) == ' ';
        if free_before && blank_after { starts.push(at); }
        at = find_text(&c, at + 1, word);
    }
    starts
}

fn replace_ref(text: &str, by: &str) -> String {
    let c: Vec<char> = nikaia_std::list::chars(text.chars());
    let mut out: String = String::from("");
    let mut from: i64 = 0;
    for at in word_starts(text, "ref") {
        out.push_str(&slice(&c, from, at));
        out.push_str(by);
        from = at + 3;
    }
    out.push_str(&slice(&c, from, c.len() as i64));
    out
}

fn variables(text: &str) -> Vec<String> {
    let c: Vec<char> = nikaia_std::list::chars(text.chars());
    let mut out: Vec<String> = vec![];
    for at in 0..c.len() as i64 {
        if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '$' {
            let mut end = at + 1;
            while end < c.len() as i64 && is_word_char(*nikaia_std::index::get(&c, nikaia_std::index::at(end))) { end += 1; }
            let name = slice(&c, at + 1, end);
            if (name.len() as i64) > 0 && !out.contains(&name) { out.push(name); }
        }
    }
    out
}

fn joined_by(parts: &Vec<String>, between: &str) -> String {
    let mut out: String = String::from("");
    for k in 0..parts.len() as i64 {
        if k > 0 { out.push_str(between); }
        out.push_str(nikaia_std::index::get(&parts, nikaia_std::index::at(k)));
    }
    out
}

fn without_dollars(text: &str) -> String {
    let mut out: String = String::from("");
    for c in text.chars() { if c != '$' { out.push(c); } }
    out
}

fn trimmed_start(written: &str) -> String { written.trim_start().to_owned() }

fn is_word_char(c: char) -> bool { is_lower(c) || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || c == '_' }

fn is_lower(c: char) -> bool { c >= 'a' && c <= 'z' }


// --- locks.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Locking {
    pub functions: collections::BTreeMap<String, Lock>,
    pub fields: collections::BTreeMap<String, Lock>,
}

pub fn locking(itself: &collections::BTreeMap<String, Lock>, callees: &collections::BTreeMap<String, collections::BTreeSet<String>>, declared: &collections::BTreeSet<String>, library: &Ledger, own: &Ledger) -> Locking {
    let mut touches = itself.to_owned();
    let mut changed = true;
    while changed {
        changed = false;
        for (name, called) in callees.iter() {
            let before = nikaia_std::index::or(match *nikaia_std::index::get(&touches, name) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || Lock::No);
            if before.holds() { continue; }
            let mut reached = Lock::No;
            for callee in called.iter() { reached = reached.or(theirs_of(&touches, library, declared, callee)); }
            let grown = before.or(reached);
            if grown != before {
                touches.insert(name.to_owned(), grown);
                changed = true;
            }
        }
    }
    let mut answer = Locking { functions: collections::BTreeMap::new(), fields: collections::BTreeMap::new() };
    for (name, holds) in touches.iter() {
        if name.starts_with("field:") {
            let c: Vec<char> = nikaia_std::list::chars(name.chars());
            let field = slice(&c, 6, c.len() as i64);
            let settled = if published(own, &field) { holds.clone().or(Lock::Undecided) } else { holds.clone() };
            answer.fields.insert(field, settled);
        } else if own.functions.contains_key(name) { answer.functions.insert(name.to_owned(), holds.clone()); }
    }
    answer
}

fn theirs_of(touches: &collections::BTreeMap<String, Lock>, library: &Ledger, declared: &collections::BTreeSet<String>, callee: &str) -> Lock {
    let constructed = format!("{}::new", callee);
    for key in [callee.to_owned(), constructed] {
        let found = match match *nikaia_std::index::get(&touches, &key) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => match described(library, &key) { Some(__nikaia_value) => __nikaia_value, None => continue } };
        return found;
    }
    if is_a_variant(declared, callee) { Lock::No } else { Lock::Undecided }
}

fn described(library: &Ledger, key: &str) -> Option<Lock> {
    let contract = match *nikaia_std::index::get(&library.functions, key) { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(contract.touches_a_lock.clone())
}

fn is_a_variant(declared: &collections::BTreeSet<String>, callee: &str) -> bool {
    let mut parts: Vec<String> = vec![];
    for part in callee.split("::") { parts.push(part.to_owned()); }
    if (parts.len() as i64) < 2 || *nikaia_std::index::get(&parts, nikaia_std::index::at(parts.len() as i64 - 1)) == "new" { return false; }
    declared.contains(&struct_type(callee))
}

fn published(own: &Ledger, field: &str) -> bool {
    let c: Vec<char> = nikaia_std::list::chars(field.chars());
    let dot = find_text(&c, 0, ".");
    if dot < 0 { return false; }
    let owner = slice(&c, 0, dot);
    let name = slice(&c, dot + 1, c.len() as i64);
    let contract = match *nikaia_std::index::get(&own.types, &owner) { Some(__nikaia_value) => __nikaia_value, None => return false };
    if !contract.public { return false; }
    for one in contract.fields.iter() { if one.name == name && one.public { return true; } }
    false
}


// --- manifest.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Switch {
    Kept,
    Moved(String),
}

pub fn known() -> Vec<String> { vec![String::from("target"), String::from("user-parallelism"), String::from("reentrancy-check"), String::from("cleanup-deadline")] }

fn withdrawn(key: &str) -> String {
    if key == "ordering" { return String::from("statements run in the order they are written, so there's nothing left for it to turn off. To run two things together, write `overlap { … }`; `--overlaps` shows which branches did"); }
    String::from("")
}

fn moved(key: &str) -> String {
    if key == "cleanup-deadline" { return String::from("the runtime configuration file `nikaia-runtime.toml`, which is read when the program starts. How long a program waits at exit is set by whoever runs it, and the compiler no longer reads this key"); }
    String::from("")
}

pub fn build_key(key: &str) -> Result<Switch, nikaia_std::error::Thrown<Refused>> {
    let gone = withdrawn(key);
    if (gone.len() as i64) > 0 { return Err(nikaia_std::error::throwing(Refused::Because(format!("`{}` in `[build]` is no longer supported: {}", key, gone)), &"build_key")); }
    if !contains(&known(), key) {
        let expected = choices(&known());
        return Err(nikaia_std::error::throwing(Refused::Because(format!("`[build]` has no key called `{}`. The keys are: {}.", key, expected)), &"build_key"));
    }
    let went = moved(key);
    if (went.len() as i64) > 0 { return Ok(Switch::Moved(format!("`{}` in `[build]` has moved to {}", key, went))); }
    Ok(Switch::Kept)
}

pub fn targets() -> Vec<String> { vec![String::from("x86_64-linux"), String::from("aarch64-linux"), String::from("wasm32-unknown")] }

pub fn codegen_keys() -> Vec<String> { vec![String::from("opt-level"), String::from("lto")] }

pub fn codegen_table(target: &str) -> Result<(), nikaia_std::error::Thrown<Refused>> {
    if !contains(&targets(), target) {
        let expected = choices(&targets());
        return Err(nikaia_std::error::throwing(Refused::Because(format!("`[build.{}]` isn't a machine Nikaia builds for. The machines are: {}.", target, expected)), &"codegen_table"));
    }
    Ok(())
}

pub fn codegen_key(target: &str, key: &str) -> Result<(), nikaia_std::error::Thrown<Refused>> {
    if !contains(&codegen_keys(), key) {
        let expected = choices(&codegen_keys());
        return Err(nikaia_std::error::throwing(Refused::Because(format!("`[build.{}]` has no key called `{}`. The keys are: {}.", target, key, expected)), &"codegen_key"));
    }
    Ok(())
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DependencyShape {
    Rust,
    Path,
    Nikaia,
}

pub fn dependency(name: &str, typed: bool, kind: &str, has_path: bool) -> Result<DependencyShape, nikaia_std::error::Thrown<Refused>> {
    if typed {
        if kind == "rust" { return Ok(DependencyShape::Rust); }
        return Err(nikaia_std::error::throwing(Refused::Because(format!("Dependency `{}` has `type = \"{}\"`, which isn't a kind of dependency Nikaia knows. The only one is `rust`, for a crate from crates.io.", name, kind)), &"dependency"));
    }
    if has_path { return Ok(DependencyShape::Path); }
    Ok(DependencyShape::Nikaia)
}

pub fn crate_name(key: &str) -> String {
    let mut name: String = String::from("");
    for c in key.chars() { if c == '-' { name.push('_'); } else { name.push(c); } }
    name
}

fn contains(words: &[String], word: &str) -> bool {
    for w in words.iter() { if w == word { return true; } }
    false
}

fn choices(words: &[String]) -> String {
    let mut out: String = String::from("");
    for w in words.iter() {
        if (out.len() as i64) > 0 { out.push_str(", "); }
        out.push_str(w);
    }
    out
}


// --- names.nika ---

pub fn names_in(expr: &Expr, words: &winnow_grammar::InternerContext, out: &mut collections::BTreeSet<String>) {
    match expr {
        Expr::Variable(name) => {
            let name = *name;
            out.insert(words.resolve(name).to_owned());
        },
        Expr::Path(segments) => { if (segments.len() as i64) > 0 { out.insert(words.resolve(*nikaia_std::index::get(&segments, 0)).to_owned()); } },
        Expr::Call { func, args, config } => {
            let func = nikaia_std::boxed::open(func);
            names_in(func, words, out);
            for arg in args.iter() { names_in(arg, words, out); }
            for setting in config.iter() { names_in(&setting.value, words, out); }
        },
        Expr::MethodCall { receiver, method, args, config } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            names_in(receiver, words, out);
            out.insert(words.resolve(method).to_owned());
            for arg in args.iter() { names_in(arg, words, out); }
            for setting in config.iter() { names_in(&setting.value, words, out); }
        },
        Expr::SafeMethod { receiver, method, args, config } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            names_in(receiver, words, out);
            out.insert(words.resolve(method).to_owned());
            for arg in args.iter() { names_in(arg, words, out); }
            for setting in config.iter() { names_in(&setting.value, words, out); }
        },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); names_in(base, words, out) },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); names_in(base, words, out) },
        Expr::Binary { lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            names_in(lhs, words, out);
            names_in(rhs, words, out);
        },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); names_in(expr, words, out) },
        Expr::Try(inner) => { let inner = nikaia_std::boxed::open(inner); names_in(inner, words, out) },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); names_in(expr, words, out) },
        Expr::Index { base, index } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            names_in(base, words, out);
            names_in(index, words, out);
        },
        Expr::Tuple(parts) => { for part in parts.iter() { names_in(part, words, out); } },
        Expr::ListLit { items, .. } => { for item in items.iter() { names_in(item, words, out); } },
        Expr::Coalesce { value, fallback } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            names_in(value, words, out);
            names_in(fallback, words, out);
        },
        Expr::Range { start, end, .. } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end);
            names_in(start, words, out);
            names_in(end, words, out);
        },
        Expr::StructLit { name, fields } => {
            let name = *name;
            out.insert(words.resolve(name).to_owned());
            for field in fields.iter() {
                out.insert(words.resolve(field.name).to_owned());
                maybe_names_in((field.value).as_ref(), words, out);
            }
        },
        Expr::With { base, fields, .. } => {
            let base = nikaia_std::boxed::open(base);
            names_in(base, words, out);
            for field in fields.iter() {
                out.insert(words.resolve(field.name).to_owned());
                maybe_names_in((field.value).as_ref(), words, out);
            }
        },
        Expr::Block(block) => names_in_block(block, words, out),
        Expr::Unsafe(block) => names_in_block(block, words, out),
        Expr::Overlap(block) => names_in_block(block, words, out),
        Expr::Closure { body, .. } => names_in_block(body, words, out),
        Expr::Select(arms) => {
            for arm in arms.iter() {
                a_symbol(arm.binding, words, out);
                names_in(&arm.value, words, out);
                names_in_block(&arm.body, words, out);
            }
        },
        Expr::If { cond, then_branch, else_branch } => {
            let cond = nikaia_std::boxed::open(cond);
            names_in(cond, words, out);
            names_in_block(then_branch, words, out);
            maybe_names_in_block((else_branch).as_ref(), words, out);
        },
        Expr::Match { value, arms } => {
            let value = nikaia_std::boxed::open(value);
            names_in(value, words, out);
            for arm in arms.iter() {
                match &arm.pattern {
                    MatchPattern::Literal(pattern) => names_in(pattern, words, out),
                    _ => { },
                }
                names_in(&arm.body, words, out);
            }
        },
        Expr::Spawn { body, .. } => { let body = nikaia_std::boxed::open(body); names_in(body, words, out) },
        Expr::Throw(thrown) => { let thrown = nikaia_std::boxed::open(thrown); names_in(thrown, words, out) },
        Expr::Return(value) => { let value = nikaia_std::boxed::open(value); maybe_names_in((value).as_ref(), words, out) },
        Expr::Break => { },
        Expr::Continue => { },
        Expr::TryCatch { expr, handler } => {
            let expr = nikaia_std::boxed::open(expr);
            names_in(expr, words, out);
            names_in_block(handler, words, out);
        },
        Expr::LitInterpolated { parts } => {
            for part in parts.iter() {
                match part {
                    FPart::Hole { expr, .. } => names_in(expr, words, out),
                    FPart::Text(_) => { },
                }
            }
        },
        Expr::Dsl { target, context, content } => {
            let context = *context; let target = *target;
            out.insert(words.resolve(target).to_owned());
            a_symbol(context, words, out);
            words_of(content, out);
        },
        Expr::Asm { bindings, code } => {
            for binding in bindings.iter() { out.insert(words.resolve(binding.variable).to_owned()); }
            words_of(code, out);
        },
        Expr::LitInt { .. } => { },
        Expr::LitFloat(_) => { },
        Expr::LitBool(_) => { },
        Expr::LitNull => { },
        Expr::LitChar(_) => { },
        Expr::LitStr { .. } => { },
    }
}

pub fn names_in_block(block: &Block, words: &winnow_grammar::InternerContext, out: &mut collections::BTreeSet<String>) { for stmt in block.stmts.iter() { names_in_statement(&stmt.node, words, out); } }

pub fn names_in_statement(stmt: &Stmt, words: &winnow_grammar::InternerContext, out: &mut collections::BTreeSet<String>) {
    match stmt {
        Stmt::Let { value, .. } => names_in(value, words, out),
        Stmt::Comptime { value, .. } => names_in(value, words, out),
        Stmt::Expr(value) => names_in(value, words, out),
        Stmt::Assign { target, value, .. } => {
            names_in(target, words, out);
            names_in(value, words, out);
        },
        Stmt::For { iter, body, .. } => {
            names_in(iter, words, out);
            names_in_block(body, words, out);
        },
        Stmt::While { cond, body } => {
            names_in(cond, words, out);
            names_in_block(body, words, out);
        },
        Stmt::Return(value) => maybe_names_in((value).as_ref(), words, out),
        Stmt::Break => { },
        Stmt::Continue => { },
    }
}

fn maybe_names_in(expr: Option<&Expr>, words: &winnow_grammar::InternerContext, out: &mut collections::BTreeSet<String>) { names_in(match expr { Some(__nikaia_value) => __nikaia_value, None => return }, words, out); }

fn maybe_names_in_block(block: Option<&Block>, words: &winnow_grammar::InternerContext, out: &mut collections::BTreeSet<String>) { names_in_block(match block { Some(__nikaia_value) => __nikaia_value, None => return }, words, out); }

fn a_symbol(name: Option<winnow_grammar::Symbol>, words: &winnow_grammar::InternerContext, out: &mut collections::BTreeSet<String>) {
    let named = match name { Some(__nikaia_value) => __nikaia_value, None => return };
    out.insert(words.resolve(named).to_owned());
}

fn words_of(text: &str, out: &mut collections::BTreeSet<String>) {
    let mut word: String = String::from("");
    for c in text.chars() {
        if c.is_alphanumeric() || c == '_' { word.push(c); } else {
            if (word.len() as i64) > 0 { out.insert(word.to_owned()); }
            word = String::from("");
        }
    }
    if (word.len() as i64) > 0 { out.insert(word); }
}


// --- paths.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Export {
    pub at: String,
    pub prefix: String,
    pub name: Option<Named>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Named {
    pub name: String,
    pub alias: String,
}

pub fn after(path: &str, word: &str) -> Option<String> {
    if path == word { return Some(String::from("")); }
    let lead = format!("{}::", word);
    if !path.starts_with(&lead) { return None; }
    let c: Vec<char> = nikaia_std::list::chars(path.chars());
    let w: Vec<char> = nikaia_std::list::chars(lead.chars());
    Some(slice(&c, w.len() as i64, c.len() as i64))
}

pub fn module_of(relative: &str) -> Option<String> {
    if !relative.starts_with("src/") || !relative.ends_with(".rs") { return None; }
    let c: Vec<char> = nikaia_std::list::chars(relative.chars());
    let inside = slice(&c, 4, c.len() as i64 - 3);
    if inside == "lib" { return Some(String::from("")); }
    if inside == "main" || inside.starts_with("bin/") { return None; }
    let mut path = inside.to_owned();
    if inside == "mod" { path = String::from(""); } else if inside.ends_with("/mod") {
        let i: Vec<char> = nikaia_std::list::chars(inside.chars());
        path = slice(&i, 0, i.len() as i64 - 4);
    }
    let mut out: String = String::from("");
    for part in path.split("/") { out = joined(&out, part); }
    Some(out)
}

pub fn joined(at: &str, name: &str) -> String {
    if at.is_empty() { return name.to_owned(); }
    if name.is_empty() { return at.to_owned(); }
    format!("{}::{}", at, name)
}

pub fn exported(at: &str, text: &str) -> Vec<Export> {
    let __keep_frame = nikaia_std::tether::Keep::new();
    let whole = text.trim();
    let c: Vec<char> = nikaia_std::list::chars(whole.chars());
    let mut out: Vec<Export> = vec![];
    let open = find_text(&c, 0, "::{");
    if open >= 0 && whole.ends_with("}") {
        let prefix = slice(&c, 0, open);
        let inside = slice(&c, open + 3, c.len() as i64 - 1);
        for one in split_top_level(&inside) { if !one.is_empty() { out.push(Export { at: at.to_owned(), prefix: prefix.to_owned(), name: Some(named(&one)) }); } }
        return out;
    }
    if whole.ends_with("::*") {
        out.push(Export { at: at.to_owned(), prefix: slice(&c, 0, c.len() as i64 - 3), name: None });
        return out;
    }
    let mut path = whole.to_owned();
    let mut alias: Option<String> = None;
    let space = find_text(&c, 0, " as ");
    if space >= 0 {
        let before = __keep_frame.put(slice(&c, 0, space));
        let after_it = __keep_frame.put(slice(&c, space + 4, c.len() as i64));
        path = before.trim().to_owned();
        alias = Some(after_it.trim().to_owned());
    }
    let p: Vec<char> = nikaia_std::list::chars(path.chars());
    let cut = find_last_text(&p, "::");
    let mut prefix: String = String::from("");
    let mut name = path.to_owned();
    if cut >= 0 {
        prefix = slice(&p, 0, cut);
        let rest = __keep_frame.put(slice(&p, cut + 2, p.len() as i64));
        name = rest.trim().to_owned();
    }
    let offered = nikaia_std::index::or(alias, || name.to_owned().into());
    out.push(Export { at: at.to_owned(), prefix, name: Some(Named { name, alias: offered }) });
    out
}

pub fn named(written: &str) -> Named {
    let one = written.trim();
    let c: Vec<char> = nikaia_std::list::chars(one.chars());
    let space = find_text(&c, 0, " as ");
    if space < 0 { return Named { name: one.to_owned(), alias: one.to_owned() }; }
    let before = slice(&c, 0, space);
    let after_it = slice(&c, space + 4, c.len() as i64);
    Named { name: before.trim().to_owned(), alias: after_it.trim().to_owned() }
}

pub fn bases(export: &Export) -> Vec<String> {
    let prefix = export.prefix.trim();
    let mut out: Vec<String> = vec![];
    let from_root = after(prefix, "crate");
    if from_root.is_some() {
        out.push(nikaia_std::index::or(from_root, || "".into()));
        return out;
    }
    let from_here = after(prefix, "self");
    if from_here.is_some() {
        out.push(joined(&export.at, nikaia_std::index::or(from_here.as_deref(), || "")));
        return out;
    }
    let from_up = after(prefix, "super");
    if from_up.is_some() {
        let a: Vec<char> = nikaia_std::list::chars(export.at.chars());
        let cut = find_last_text(&a, "::");
        let mut parent: String = String::from("");
        if cut >= 0 { parent = slice(&a, 0, cut); }
        out.push(joined(&parent, nikaia_std::index::or(from_up.as_deref(), || "")));
        return out;
    }
    let here = joined(&export.at, prefix);
    let root = prefix.to_owned();
    if here != root { out.push(here); }
    out.push(root);
    out
}

pub fn split_top_level(text: &str) -> Vec<String> {
    let mut out: Vec<String> = vec![];
    let mut depth = 0;
    let mut current: String = String::from("");
    for c in text.chars() {
        if c == '<' || c == '(' || c == '[' { depth += 1; } else if c == '>' || c == ')' || c == ']' { depth -= 1; } else if c == ',' && depth == 0 {
            out.push(current.trim().to_owned());
            current = String::from("");
            continue;
        }
        current.push(c);
    }
    let last = current.trim();
    if !last.is_empty() { out.push(last.to_owned()); }
    out
}

fn find_last_text(c: &[char], word: &str) -> i64 {
    let w: Vec<char> = nikaia_std::list::chars(word.chars());
    let mut found: i64 = -1;
    if w.is_empty() || (c.len() as i64) < w.len() as i64 { return found; }
    for at in 0..c.len() as i64 - w.len() as i64 + 1 { if stands_at(c, at, &w) { found = at; } }
    found
}

fn stands_at(c: &[char], at: i64, w: &[char]) -> bool {
    for k in 0..w.len() as i64 { if *nikaia_std::index::get(&c, nikaia_std::index::at(at + k)) != *nikaia_std::index::get(&w, nikaia_std::index::at(k)) { return false; } }
    true
}


// --- rust.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Part<'a> {
    pub name: &'a str,
    pub ty: &'a str,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Fun<'a> {
    pub name: &'a str,
    pub generics: &'a str,
    pub calls: Vec<&'a str>,
    pub wheres: &'a str,
    pub pauses: bool,
    pub parts: Vec<Part<'a>>,
    pub result: &'a str,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Rec<'a> {
    pub what: &'a str,
    pub name: &'a str,
    pub parts: Vec<Part<'a>>,
    pub derives: Vec<&'a str>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Group<'a> {
    pub what: &'a str,
    pub name: &'a str,
    pub via: &'a str,
    pub visible: bool,
    pub items: Vec<RustItem<'a>>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RustItem<'a> {
    Fun(Fun<'a>),
    Rec(Rec<'a>),
    Group(Group<'a>),
    Hidden(Fun<'a>),
    Used(&'a str),
    Export(&'a str),
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Found<'a> {
    One(RustItem<'a>),
    Skip,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Called<'a> {
    One(&'a str),
    Many(Vec<&'a str>),
    Nothing,
}

grammar! {
    grammar Rust {

        rule WSE =
            multispace1
            -> { }

        rule WS =
            (WSE | LINE | BLOCK)*
            -> { }

        rule LINE =
            "//" until(line_ending)
            -> { }

        rule BLOCK =
            "/*" until("*/") "*/"
            -> { }

        pub rule file -> Vec<RustItem<'a>> =
            items:public eof
            -> { items }

        rule public -> Vec<RustItem<'a>> =
            found:found*
            -> { kept(found) }

        rule exposed -> Vec<RustItem<'a>> =
            found:found_exposed*
            -> { kept(found) }

        rule found -> Found<'a> =
            i:item
            -> { Found::One(i) }
          | f:method
            -> { Found::One(RustItem::Hidden(f)) }
          | JUNK
            -> { Found::Skip }

        rule found_exposed -> Found<'a> =
            f:method
            -> { Found::One(RustItem::Fun(f)) }
          | i:item
            -> { Found::One(i) }
          | JUNK
            -> { Found::Skip }

        rule item -> RustItem<'a> =
            f:function
            -> { RustItem::Fun(f) }
          | r:record
            -> { RustItem::Rec(r) }
          | g:group
            -> { RustItem::Group(g) }
          | e:export
            -> { RustItem::Export(e) }
          | u:import
            -> { RustItem::Used(u) }

        rule export -> &'a str =
            PUB USE t:USE_TEXT ";"
            -> { t }

        rule import -> &'a str =
            USE t:USE_TEXT ";"
            -> { t }

        rule USE_TEXT -> &'a str =
            s:text(USE_RUN)
            -> { s.trim() }

        rule USE_RUN =
            USE_PIECE+
            -> { }

        rule USE_PIECE =
            not(";") (BRACES | LINE | BLOCK | ANY)
            -> { }

        rule function -> Fun<'a> =
            PUB f:method
            -> { f }

        rule method -> Fun<'a> =
            pauses:qualifiers FN name:IDENT g:generics parts:parameters result:result w:where_clause c:tail
            -> { Fun { name, generics: g, wheres: w, calls: c, pauses, parts, result } }

        rule qualifiers -> bool =
            qs:qualifier*
            -> {
                let mut pauses = false;
                for q in qs.into_iter() { if q { pauses = true; } }
                pauses
            }

        rule qualifier -> bool =
            ASYNC
            -> { true }
          | CONST
            -> { false }
          | UNSAFE
            -> { false }
          | EXTERN abi
            -> { false }

        rule abi =
            string
            -> { }
          | empty
            -> { }

        rule tail -> Vec<&'a str> =
            cs:inside
            -> { cs }
          | ";"
            -> { Vec::new() }

        rule inside -> Vec<&'a str> =
            "{" cs:inside_run "}"
            -> { cs }

        rule inside_run -> Vec<&'a str> =
            pieces:inside_piece*
            -> { every_call(pieces) }

        rule inside_piece -> Called<'a> =
            not("}") STRING
            -> { Called::Nothing }
          | not("}") CHAR
            -> { Called::Nothing }
          | not("}") LINE
            -> { Called::Nothing }
          | not("}") BLOCK
            -> { Called::Nothing }
          | not("}") inner:inside
            -> { Called::Many(inner) }
          | not("}") p:CALL
            -> { Called::One(p) }
          | not("}") ANY
            -> { Called::Nothing }

        rule CALL -> &'a str =
            p:text(PATH) TURBOFISH "("
            -> { p }

        rule PATH =
            raw_ident(PATH_TAIL)*
            -> { }

        rule PATH_TAIL =
            "::" raw_ident
            -> { }

        rule TURBOFISH =
            "::" ANGLES
            -> { }
          | empty
            -> { }

        rule parameters -> Vec<Part<'a>> =
            "(" ps:parameter_list ")"
            -> { ps }

        rule parameter_list -> Vec<Part<'a>> =
            head:parameter tail:parameter_tail* COMMA
            -> {
                let mut all = Vec::new();
                all.push(head);
                for p in tail.into_iter() { all.push(p); }
                all
            }
          | empty
            -> { Vec::new() }

        rule parameter_tail -> Part<'a> =
            "," p:parameter
            -> { p }

        rule parameter -> Part<'a> =
            t:text(receiver)
            -> { Part { name: "self", ty: t.trim() } }
          | MUT n:IDENT ":" t:PARAM_TYPE
            -> { Part { name: n, ty: t } }
          | n:IDENT ":" t:PARAM_TYPE
            -> { Part { name: n, ty: t } }
          | n:HOLE ":" t:PARAM_TYPE
            -> { Part { name: n, ty: t } }

        rule receiver =
            "&" LIFETIME MUT SELF
            -> { }
          | "&" LIFETIME SELF
            -> { }
          | "&" MUT SELF
            -> { }
          | "&" SELF
            -> { }
          | MUT SELF
            -> { }
          | SELF
            -> { }

        rule record -> Rec<'a> =
            ds:attributes PUB STRUCT name:IDENT generics where_clause "{" fs:field_list "}"
            -> { Rec { what: "struct", name, parts: fs, derives: ds } }
          | ds:attributes PUB STRUCT name:IDENT generics tuple_body where_clause ";"
            -> { Rec { what: "struct", name, parts: Vec::new(), derives: ds } }
          | ds:attributes PUB ENUM name:IDENT generics where_clause "{" vs:variant_list "}"
            -> { Rec { what: "enum", name, parts: vs, derives: ds } }

        rule attributes -> Vec<&'a str> =
            all:attribute*
            -> {
                let mut derives = Vec::new();
                for d in all.into_iter() { if !d.is_empty() { derives.push(d); } }
                derives
            }

        rule attribute -> &'a str =
            "#" "[" DERIVE "(" d:text(TUPLE_INNER) ")" "]"
            -> { d.trim() }
          | "#" "[" BRACKET_INNER "]"
            -> { "" }

        rule tuple_body =
            "(" TUPLE_INNER ")"
            -> { }
          | empty
            -> { }

        rule field_list -> Vec<Part<'a>> =
            head:field tail:field_tail* COMMA
            -> {
                let mut all = Vec::new();
                all.push(head);
                for f in tail.into_iter() { all.push(f); }
                all
            }
          | empty
            -> { Vec::new() }

        rule field_tail -> Part<'a> =
            "," f:field
            -> { f }

        rule field -> Part<'a> =
            PUB n:IDENT ":" t:FIELD_TYPE
            -> { Part { name: n, ty: t } }
          | n:IDENT ":" t:FIELD_TYPE
            -> { Part { name: n, ty: t } }

        rule variant_list -> Vec<Part<'a>> =
            head:variant tail:variant_tail* COMMA
            -> {
                let mut all = Vec::new();
                all.push(head);
                for v in tail.into_iter() { all.push(v); }
                all
            }
          | empty
            -> { Vec::new() }

        rule variant_tail -> Part<'a> =
            "," v:variant
            -> { v }

        rule variant -> Part<'a> =
            n:IDENT t:text(payload)
            -> { Part { name: n, ty: t.trim() } }

        rule payload =
            "(" TUPLE_INNER ")"
            -> { }
          | "{" BRACE_INNER "}"
            -> { }
          | empty
            -> { }

        rule group -> Group<'a> =
            UNSAFE IMPL generics v:IMPL_TYPE FOR t:IMPL_TYPE where_clause "{" items:exposed "}"
            -> { Group { what: "unsafe impl", name: t, via: v, visible: true, items } }
          | UNSAFE IMPL generics t:IMPL_TYPE where_clause "{" items:public "}"
            -> { Group { what: "unsafe impl", name: t, via: "", visible: true, items } }
          | IMPL generics v:IMPL_TYPE FOR t:IMPL_TYPE where_clause "{" items:exposed "}"
            -> { Group { what: "impl", name: t, via: v, visible: true, items } }
          | IMPL generics t:IMPL_TYPE where_clause "{" items:public "}"
            -> { Group { what: "impl", name: t, via: "", visible: true, items } }
          | PUB TRAIT name:IDENT generics where_clause "{" items:exposed "}"
            -> { Group { what: "trait", name, via: "", visible: true, items } }
          | PUB MOD name:IDENT "{" items:public "}"
            -> { Group { what: "mod", name, via: "", visible: true, items } }
          | PUB MOD name:IDENT ";"
            -> { Group { what: "mod", name, via: "", visible: true, items: Vec::new() } }
          | MOD name:IDENT "{" items:public "}"
            -> { Group { what: "mod", name, via: "", visible: false, items } }
          | MOD name:IDENT ";"
            -> { Group { what: "mod", name, via: "", visible: false, items: Vec::new() } }

        rule generics -> &'a str =
            "<" g:text(ANGLE_INNER) ">"
            -> { g.trim() }
          | empty
            -> { "" }

        rule where_clause -> &'a str =
            WHERE w:text(WHERE_RUN)
            -> { w.trim() }
          | empty
            -> { "" }

        rule PARAM_TYPE -> &'a str =
            s:text(PARAM_RUN)
            -> { s.trim() }

        rule PARAM_RUN =
            PARAM_PIECE+
            -> { }

        rule PARAM_PIECE =
            not(",") not(")") SPAN
            -> { }

        rule FIELD_TYPE -> &'a str =
            s:text(FIELD_RUN)
            -> { s.trim() }

        rule FIELD_RUN =
            FIELD_PIECE+
            -> { }

        rule FIELD_PIECE =
            not(",") not("}") SPAN
            -> { }

        rule result -> &'a str =
            "->" t:RESULT_TYPE
            -> { t }
          | empty
            -> { "" }

        rule RESULT_TYPE -> &'a str =
            s:text(RESULT_RUN)
            -> { s.trim() }

        rule RESULT_RUN =
            RESULT_PIECE+
            -> { }

        rule RESULT_PIECE =
            not("{") not(";") not(WHERE) SPAN
            -> { }

        rule WHERE_RUN =
            WHERE_PIECE+
            -> { }

        rule WHERE_PIECE =
            not("{") not(";") SPAN
            -> { }

        rule IMPL_TYPE -> &'a str =
            s:text(IMPL_RUN)
            -> { s.trim() }

        rule IMPL_RUN =
            IMPL_PIECE+
            -> { }

        rule IMPL_PIECE =
            not("{") not(WHERE) not(FOR) SPAN
            -> { }

        rule SPAN =
            (ANGLES | PARENS | BRACKETS | STRING | CHAR | LINE | BLOCK | ANY)
            -> { }

        rule JUNK =
            not("}") (STRING | CHAR | LINE | BLOCK | BRACES | ANY)
            -> { }

        rule BRACES =
            "{" BRACE_INNER "}"
            -> { }

        rule BRACE_INNER =
            BRACE_PIECE*
            -> { }

        rule BRACE_PIECE =
            not("}") (STRING | CHAR | LINE | BLOCK | BRACES | ANY)
            -> { }

        rule PARENS =
            "(" TUPLE_INNER ")"
            -> { }

        rule TUPLE_INNER =
            PAREN_PIECE*
            -> { }

        rule PAREN_PIECE =
            not(")") (STRING | CHAR | LINE | BLOCK | PARENS | BRACES | BRACKETS | ANGLES | ANY)
            -> { }

        rule BRACKETS =
            "[" BRACKET_INNER "]"
            -> { }

        rule BRACKET_INNER =
            BRACKET_PIECE*
            -> { }

        rule BRACKET_PIECE =
            not("]") (STRING | CHAR | LINE | BLOCK | PARENS | BRACES | BRACKETS | ANGLES | ANY)
            -> { }

        rule ANGLES =
            "<" ANGLE_INNER ">"
            -> { }

        rule ANGLE_INNER =
            ANGLE_PIECE*
            -> { }

        rule ANGLE_PIECE =
            not(">") (STRING | CHAR | LINE | BLOCK | PARENS | BRACKETS | ANGLES | ANY)
            -> { }

        rule STRING =
            "\"" (SESC | SPLAIN)* "\""
            -> { }

        rule SESC =
            "\\" any
            -> { }

        rule SPLAIN =
            not("\"") not("\\") any
            -> { }

        rule CHAR =
            "'" (CESC | CPLAIN) "'"
            -> { }

        rule CESC =
            "\\" any
            -> { }

        rule CPLAIN =
            not("'") not("\\") any
            -> { }

        rule ANY =
            any
            -> { }

        rule PUB =
            "pub" not(WORD) not("(")
            -> { }

        rule FN =
            "fn" not(WORD)
            -> { }

        rule ASYNC =
            "async" not(WORD)
            -> { }

        rule CONST =
            "const" not(WORD)
            -> { }

        rule UNSAFE =
            "unsafe" not(WORD)
            -> { }

        rule EXTERN =
            "extern" not(WORD)
            -> { }

        rule STRUCT =
            "struct" not(WORD)
            -> { }

        rule DERIVE =
            "derive" not(WORD)
            -> { }

        rule ENUM =
            "enum" not(WORD)
            -> { }

        rule TRAIT =
            "trait" not(WORD)
            -> { }

        rule IMPL =
            "impl" not(WORD)
            -> { }

        rule MOD =
            "mod" not(WORD)
            -> { }

        rule FOR =
            "for" not(WORD)
            -> { }

        rule WHERE =
            "where" not(WORD)
            -> { }

        rule MUT =
            "mut" not(WORD)
            -> { }

        rule USE =
            "use" not(WORD)
            -> { }

        rule SELF =
            "self" not(WORD)
            -> { }

        rule WORD =
            alpha1
            -> { }
          | digit
            -> { }
          | "_"
            -> { }

        rule IDENT -> &'a str =
            s:raw_ident
            -> { s }

        rule HOLE -> &'a str =
            s:text("_")
            -> { s }

        rule LIFETIME =
            "'" raw_ident
            -> { }

        rule COMMA =
            ","
            -> { }
          | empty
            -> { }
    }
}

fn every_call(pieces: Vec<Called<'_>>) -> Vec<&str> {
    let mut all = Vec::new();
    for piece in pieces.into_iter() {
        match piece {
            Called::One(one) => { all.push(one); },
            Called::Many(ref many) => {
                for one in many.iter() {
                    let one = *one;
                    all.push(one);
                }
            },
            Called::Nothing => { },
        }
    }
    all
}

fn kept(found: Vec<Found<'_>>) -> Vec<RustItem<'_>> {
    let mut all = Vec::new();
    for f in found.into_iter() {
        match f {
            Found::One(item) => { all.push(item); },
            Found::Skip => { },
        }
    }
    all
}


// --- signature.nika ---

#[derive(Debug, Clone)]
pub struct Translated {
    pub ty: Ty,
    pub kept: bool,
}

#[derive(Debug, Clone)]
pub struct Resulted {
    pub ty: Ty,
    pub fails: Option<String>,
}

pub fn translate(written: &str, crate_word: &str, parameters: &Vec<String>, types: &collections::BTreeSet<String>, mentioned: &mut collections::BTreeSet<String>) -> Translated {
    let text = written.trim();
    if text.starts_with("&mut ") { return Translated { ty: Ty::Unknown, kept: false }; }
    if text.starts_with("&") {
        let c: Vec<char> = nikaia_std::list::chars(text.chars());
        let rest = slice(&c, 1, c.len() as i64);
        let inner = translate(&rest, crate_word, parameters, types, mentioned);
        return Translated { ty: view_of(inner.ty), kept: false };
    }
    let optional = generic_of(text, "Option");
    if optional.is_some() {
        let inner = translate(nikaia_std::index::or(optional.as_deref(), || ""), crate_word, parameters, types, mentioned);
        return Translated { ty: Ty::Nullable(Box::new(inner.ty)), kept: inner.kept };
    }
    let listed = generic_of(text, "Vec");
    if listed.is_some() {
        let inner = translate(nikaia_std::index::or(listed.as_deref(), || ""), crate_word, parameters, types, mentioned);
        return Translated { ty: Ty::Named { name: String::from("Vec"), args: vec![inner.ty], view: false }, kept: true };
    }
    for parameter in parameters.iter() { if text == parameter { return Translated { ty: Ty::Var { name: text.to_owned(), view: false }, kept: true }; } }
    if is_plain(text) { return Translated { ty: Ty::Named { name: text.to_owned(), args: vec![], view: false }, kept: false }; }
    if text == "String" { return Translated { ty: Ty::Named { name: String::from("String"), args: vec![], view: false }, kept: true }; }
    if types.contains(text) {
        mentioned.insert(text.to_owned());
        return Translated { ty: Ty::Named { name: format!("{}::{}", crate_word, text), args: vec![], view: false }, kept: true };
    }
    Translated { ty: Ty::Unknown, kept: true }
}

pub fn result_of(written: &str, crate_word: &str, parameters: &Vec<String>, types: &collections::BTreeSet<String>, mentioned: &mut collections::BTreeSet<String>) -> Resulted {
    let resulted = generic_of(written, "Result");
    if resulted.is_none() {
        let plain = translate(written, crate_word, parameters, types, mentioned);
        return Resulted { ty: plain.ty, fails: None };
    }
    let parts = split_top_level(nikaia_std::index::or(resulted.as_deref(), || ""));
    let mut ok: String = String::from("");
    if (parts.len() as i64) > 0 { ok = (*nikaia_std::index::get(&parts, 0)).to_owned(); }
    let fine = translate(&ok, crate_word, parameters, types, mentioned);
    let mut fails: String = String::from("?");
    if (parts.len() as i64) > 1 {
        let error = (*nikaia_std::index::get(&parts, 1)).trim();
        if types.contains(error) { fails = format!("{}::{}", crate_word, error); }
    }
    Resulted { ty: fine.ty, fails: Some(fails) }
}

pub fn view_of(ty: Ty) -> Ty {
    match ty {
        Ty::Named { name, args, .. } => Ty::Named { name, args, view: true },
        Ty::Var { name, .. } => Ty::Var { name, view: true },
        _ => ty,
    }
}

pub fn sent_across(names: &Vec<String>, types: &Vec<String>, bounds: &str) -> Vec<String> {
    let sent = sends(bounds);
    let mut out: Vec<String> = vec![];
    for at in 0..names.len() as i64 {
        let ty = (*nikaia_std::index::get(&types, nikaia_std::index::at(at))).trim();
        let named = unreferenced(ty);
        let mut reached = bounds_send(ty);
        for one in sent.iter() { if *one == named { reached = true; } }
        if reached { out.push((*nikaia_std::index::get(&names, nikaia_std::index::at(at))).to_owned()); }
    }
    out
}

pub fn sends(bounds: &str) -> Vec<String> {
    let __keep_frame = nikaia_std::tether::Keep::new();
    let mut out: Vec<String> = vec![];
    for one in split_top_level(bounds) {
        let c: Vec<char> = nikaia_std::list::chars(one.chars());
        let colon = find(&c, 0, ':');
        if colon < 0 { continue; }
        let head = __keep_frame.put(slice(&c, 0, colon));
        let name = head.trim();
        let bound = slice(&c, colon + 1, c.len() as i64);
        if bounds_send(&bound) && !name.is_empty() && !name.starts_with("'") && !out.contains(&name.to_owned()) { out.push(name.to_owned()); }
    }
    out.sort();
    out
}

fn unreferenced(ty: &str) -> String {
    let c: Vec<char> = nikaia_std::list::chars(ty.chars());
    let mut from: i64 = 0;
    while from < c.len() as i64 && (*nikaia_std::index::get(&c, nikaia_std::index::at(from)) == '&' || *nikaia_std::index::get(&c, nikaia_std::index::at(from)) == ' ') { from += 1; }
    let rest = slice(&c, from, c.len() as i64);
    let trimmed = rest.trim();
    if trimmed.starts_with("mut ") {
        let t: Vec<char> = nikaia_std::list::chars(trimmed.chars());
        let after = slice(&t, 4, t.len() as i64);
        return after.to_owned();
    }
    trimmed.to_owned()
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct WrittenFn {
    pub names: Vec<String>,
    pub types: Vec<String>,
    pub result: String,
    pub pauses: bool,
    pub parameters: Vec<String>,
}

pub fn contract(written: &WrittenFn, crate_word: &str, types: &collections::BTreeSet<String>, mentioned: &mut collections::BTreeSet<String>) -> FnContract {
    let mut keeps: Vec<String> = vec![];
    let mut params: Vec<(String, Ty)> = vec![];
    for at in 0..written.names.len() as i64 {
        let translated = translate(nikaia_std::index::get(&written.types, nikaia_std::index::at(at)), crate_word, &written.parameters, types, mentioned);
        if translated.kept { keeps.push((*nikaia_std::index::get(&written.names, nikaia_std::index::at(at))).to_owned()); }
        params.push(((*nikaia_std::index::get(&written.names, nikaia_std::index::at(at))).to_owned(), translated.ty));
    }
    let mut fails: Vec<String> = vec![];
    let mut answer: Option<Ty> = None;
    if !written.result.is_empty() {
        let resulted = result_of(&written.result, crate_word, &written.parameters, types, mentioned);
        if resulted.fails.is_some() { fails.push(nikaia_std::index::or(resulted.fails, || "?".into())); }
        answer = Some(resulted.ty);
    }
    let mut signature = Signature::empty();
    signature.params = params;
    signature.result = answer;
    let mut entry = FnContract::empty();
    entry.public = true;
    entry.sync_claim = if written.pauses { Sync::No } else { Sync::Asserted };
    entry.fails_with = fails;
    entry.keeps = keeps;
    entry.signature = Some(signature);
    entry
}


