#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Position {
    Text,
    QuotedAttribute,
    Url,
    UnquotedAttribute,
    Script,
    Style,
    Comment,
}

impl Position {
    // sync (Part II, 12.1): pure CPU, cannot pause. Checked before
    // this was written - see `contracts::sync`.
    pub fn escapable(&self) -> bool { matches!(self, Position::Text | Position::QuotedAttribute) }
    // sync (Part II, 12.1): pure CPU, cannot pause. Checked before
    // this was written - see `contracts::sync`.
    pub fn why(&self) -> &str {
        match self {
            Position::Url => "a URL needs percent-encoding and a scheme check, not HTML escaping: `javascript:` survives every one of the five characters",
            Position::UnquotedAttribute => "an unquoted attribute value ends at the first blank, so a space in the value starts a new attribute - quote it and the hole is legal",
            Position::Script => "a `<script>` body is JavaScript, where `&lt;` is not `<` and `</script>` inside a string still ends the element",
            Position::Style => "a CSS block needs CSS escaping, which is a different table",
            Position::Comment => "a comment ends at the first `-->`, and escaping does not produce or remove one",
            _ => "",
        }
    }
    // sync (Part II, 12.1): pure CPU, cannot pause. Checked before
    // this was written - see `contracts::sync`.
    pub fn name(&self) -> &str {
        match self {
            Position::Text => "a text node",
            Position::QuotedAttribute => "a quoted attribute value",
            Position::Url => "a URL attribute",
            Position::UnquotedAttribute => "an unquoted attribute value",
            Position::Script => "a `<script>` body",
            Position::Style => "a `<style>` block",
            Position::Comment => "an HTML comment",
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Segment {
    Text(String),
    Hole { expr: String, at: Position },
    For { binding: String, collection: String, body: Vec<Segment> },
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn literal_length(segments: &[Segment]) -> i64 {
    let mut total: i64 = 0;
    for segment in segments.iter() {
        match segment {
            Segment::Text(text) => { total += text.len() as i64; },
            Segment::For { body, .. } => { total += literal_length(body); },
            _ => { },
        }
    }
    total
}

pub fn split(body: &str) -> Result<Vec<Segment>, nikaia_std::error::Thrown<Refused>> {
    let mut splitter = Splitter { c: nikaia_std::list::chars(body.chars()), at: 0, scan: Scan { state: ScanState::Text, tail: vec![], attribute: String::from("") } };
    let segments = splitter.until(false)?;
    if splitter.at < splitter.c.len() as i64 { return Err(nikaia_std::error::throwing(Refused::Because(String::from("`</for>` without a `<for …>` before it")), &"split")); }
    Ok(segments)
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn illegal(segments: &[Segment]) -> Vec<(String, Position)> {
    let mut found: Vec<(String, Position)> = vec![];
    for segment in segments.iter() {
        match segment {
            Segment::Hole { expr, at } => { if !at.escapable() { found.push((expr.to_owned(), at.clone())); } },
            Segment::For { body, .. } => { for inner in illegal(body) { found.push(inner); } },
            _ => { },
        }
    }
    found
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
pub fn illegal_message(expr: &str, at: &Position) -> String {
    let name = at.name();
    let why = at.why();
    format!("`{{{}}}` is in {}, which this template cannot escape for\n     = {}\n     = every hole is escaped, every time, and a position where that is not enough is an error rather than a promise that quietly does not hold (ADR-017 D1, D3)", expr, name, why)
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct Splitter {
    c: Vec<char>,
    at: i64,
    scan: Scan,
}

impl Splitter {
    fn until(&mut self, inside: bool) -> Result<Vec<Segment>, nikaia_std::error::Thrown<Refused>> {
        let mut segments: Vec<Segment> = vec![];
        let mut text: String = String::from("");
        while self.at < self.c.len() as i64 {
            if self.here("</for>") {
                if inside {
                    self.at += 6;
                    if (text.len() as i64) > 0 { segments.push(Segment::Text(text)); }
                    return Ok(segments);
                }
                return Ok(segments);
            }
            if self.here("<for") && self.at + 4 < self.c.len() as i64 && blank(*nikaia_std::index::get(&self.c, nikaia_std::index::at(self.at + 4))) {
                let (binding, collection) = self.loop_header()?;
                if (text.len() as i64) > 0 {
                    segments.push(Segment::Text(text));
                    text = String::from("");
                }
                let body = self.until(true)?;
                segments.push(Segment::For { binding, collection, body });
                continue;
            }
            let c = *nikaia_std::index::get(&self.c, nikaia_std::index::at(self.at));
            let next = self.at + 1 < self.c.len() as i64;
            if c == '{' && next && *nikaia_std::index::get(&self.c, nikaia_std::index::at(self.at + 1)) == '{' {
                text.push('{');
                self.at += 2;
            } else if c == '}' && next && *nikaia_std::index::get(&self.c, nikaia_std::index::at(self.at + 1)) == '}' {
                text.push('}');
                self.at += 2;
            } else if c == '{' {
                let position = self.scan.position();
                let mut close = self.at + 1;
                while close < self.c.len() as i64 && *nikaia_std::index::get(&self.c, nikaia_std::index::at(close)) != '}' { close += 1; }
                if close == self.c.len() as i64 {
                    let at = self.at;
                    return Err(nikaia_std::error::throwing(Refused::Because(format!("unclosed `{{` in the template, at character {}", at)), &"until"));
                }
                let mut expr: String = String::from("");
                for k in self.at + 1..close { expr.push(*nikaia_std::index::get(&self.c, nikaia_std::index::at(k))); }
                if (text.len() as i64) > 0 {
                    segments.push(Segment::Text(text));
                    text = String::from("");
                }
                segments.push(Segment::Hole { expr: expr.trim().to_owned(), at: position });
                self.at = close + 1;
            } else {
                self.scan.feed(c);
                text.push(c);
                self.at += 1;
            }
        }
        if inside { return Err(nikaia_std::error::throwing(Refused::Because(String::from("a `<for …>` in the template is never closed")), &"until")); }
        if (text.len() as i64) > 0 { segments.push(Segment::Text(text)); }
        Ok(segments)
    }
    // sync (Part II, 12.1): pure CPU, cannot pause. Checked before
    // this was written - see `contracts::sync`.
    fn here(&self, word: &str) -> bool {
        let mut k = self.at;
        for w in word.chars() {
            if k >= self.c.len() as i64 || *nikaia_std::index::get(&self.c, nikaia_std::index::at(k)) != w { return false; }
            k += 1;
        }
        true
    }
    fn loop_header(&mut self) -> Result<(String, String), nikaia_std::error::Thrown<Refused>> {
        let mut close = self.at;
        while close < self.c.len() as i64 && *nikaia_std::index::get(&self.c, nikaia_std::index::at(close)) != '>' { close += 1; }
        if close == self.c.len() as i64 { return Err(nikaia_std::error::throwing(Refused::Because(String::from("`<for` in the template is never closed with `>`")), &"loop_header")); }
        let mut header: String = String::from("");
        for k in self.at + 4..close { header.push(*nikaia_std::index::get(&self.c, nikaia_std::index::at(k))); }
        self.at = close + 1;
        let mut words: Vec<String> = vec![];
        for word in header.split_whitespace() { words.push(word.to_owned()); }
        if (words.len() as i64) != 3 || *nikaia_std::index::get(&words, 1) != "in" { return Err(nikaia_std::error::throwing(Refused::Because(format!("a template loop is written `<for name in :collection>`, not `<for{}>`", header)), &"loop_header")); }
        let binding = (*nikaia_std::index::get(&words, 0)).to_owned();
        let written = (*nikaia_std::index::get(&words, 2)).to_owned();
        if !written.starts_with(":") { return Err(nikaia_std::error::throwing(Refused::Because(format!("`{}` is captured from the enclosing scope, so it is written `:{}` - the colon is where the template's names end and the program's begin (ADR-007 D4)", written, written)), &"loop_header")); }
        let mut collection: String = String::from("");
        let mut first = true;
        for ch in written.chars() {
            if !first { collection.push(ch); }
            first = false;
        }
        Ok((binding, collection))
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct Scan {
    state: ScanState,
    tail: Vec<char>,
    attribute: String,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ScanState {
    Text,
    Tag,
    Equals,
    Quoted(char),
    Unquoted,
    Script,
    Style,
    Comment,
}

impl Scan {
    // sync (Part II, 12.1): pure CPU, cannot pause. Checked before
    // this was written - see `contracts::sync`.
    fn position(&self) -> Position {
        match &self.state {
            ScanState::Text => Position::Text,
            ScanState::Script => Position::Script,
            ScanState::Style => Position::Style,
            ScanState::Comment => Position::Comment,
            ScanState::Quoted(_) => quoted(&self.attribute),
            _ => Position::UnquotedAttribute,
        }
    }
    // sync (Part II, 12.1): pure CPU, cannot pause. Checked before
    // this was written - see `contracts::sync`.
    fn ended_with(&self, word: &str) -> bool {
        let tail: String = self.tail.iter().copied().collect();
        tail.ends_with(word)
    }
    // sync (Part II, 12.1): pure CPU, cannot pause. Checked before
    // this was written - see `contracts::sync`.
    fn saw(&self, word: &str) -> bool {
        let tail: String = self.tail.iter().copied().collect();
        tail.contains(word)
    }
    // sync (Part II, 12.1): pure CPU, cannot pause. Checked before
    // this was written - see `contracts::sync`.
    fn feed(&mut self, c: char) {
        self.tail.push(c.to_ascii_lowercase());
        if (self.tail.len() as i64) > 9 {
            let mut kept: Vec<char> = vec![];
            for k in self.tail.len() as i64 - 9..self.tail.len() as i64 { kept.push(*nikaia_std::index::get(&self.tail, nikaia_std::index::at(k))); }
            self.tail = kept;
        }
        match &self.state {
            ScanState::Text => {
                if self.ended_with("<!--") { self.state = ScanState::Comment; } else if c == '<' {
                    self.state = ScanState::Tag;
                    self.attribute = String::from("");
                }
            },
            ScanState::Comment => { if self.ended_with("-->") { self.state = ScanState::Text; } },
            ScanState::Quoted(quote) => {
                let quote = *quote;
                if c == quote {
                    self.state = ScanState::Tag;
                    self.attribute = String::from("");
                }
            },
            ScanState::Script => { if self.ended_with("</script") { self.state = ScanState::Tag; } },
            ScanState::Style => { if self.ended_with("</style") { self.state = ScanState::Tag; } },
            _ => self.in_a_tag(c),
        }
    }
    // sync (Part II, 12.1): pure CPU, cannot pause. Checked before
    // this was written - see `contracts::sync`.
    fn in_a_tag(&mut self, c: char) {
        let tag = matches!(self.state, ScanState::Tag);
        let equals = matches!(self.state, ScanState::Equals);
        let unquoted = matches!(self.state, ScanState::Unquoted);
        if self.ended_with("<!--") {
            self.state = ScanState::Comment;
            self.attribute = String::from("");
        } else if c == '>' {
            if self.saw("<script") { self.state = ScanState::Script; } else if self.saw("<style") { self.state = ScanState::Style; } else { self.state = ScanState::Text; }
            self.attribute = String::from("");
        } else if c == '=' && tag { self.state = ScanState::Equals; } else if equals { if c == '"' || c == '\'' { self.state = ScanState::Quoted(c); } else if !blank(c) { self.state = ScanState::Unquoted; } } else if unquoted && blank(c) {
            self.state = ScanState::Tag;
            self.attribute = String::from("");
        } else if tag { if blank(c) || c == '<' { self.attribute = String::from(""); } else { self.attribute.push(c.to_ascii_lowercase()); } }
    }
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn quoted(attribute: &str) -> Position {
    match attribute {
        "href" => Position::Url,
        "src" => Position::Url,
        "action" => Position::Url,
        "formaction" => Position::Url,
        "data" => Position::Url,
        "poster" => Position::Url,
        "xlink:href" => Position::Url,
        _ => Position::QuotedAttribute,
    }
}

// sync (Part II, 12.1): pure CPU, cannot pause. Checked before
// this was written - see `contracts::sync`.
fn blank(c: char) -> bool { c.is_whitespace() }


// --- throws.nika ---

pub fn error_sets(direct: &collections::BTreeMap<String, collections::BTreeSet<String>>, calls: &collections::BTreeMap<String, collections::BTreeSet<String>>, own: &Ledger) -> collections::BTreeMap<String, Vec<String>> {
    let mut sets = direct.to_owned();
    let mut changed = true;
    while changed {
        changed = false;
        for (name, callees) in calls.iter() {
            let before = nikaia_std::index::or(match *nikaia_std::index::get(&sets, name) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || collections::BTreeSet::new().into());
            let mut grown = before.to_owned();
            for callee in callees.iter() { for error in theirs(&sets, own, callee) { grown.insert(error); } }
            if (grown.len() as i64) != before.len() as i64 {
                sets.insert(name.to_owned(), grown);
                changed = true;
            }
        }
    }
    let mut settled: collections::BTreeMap<String, Vec<String>> = collections::BTreeMap::new();
    for (name, set) in sets.iter() {
        let contract = match *nikaia_std::index::get(&own.functions, name) { Some(__nikaia_value) => __nikaia_value, None => continue };
        if (contract.fails_with.len() as i64) == 0 { continue; }
        let mut errors: Vec<String> = vec![];
        for error in set.iter() { errors.push(error.to_owned()); }
        if (errors.len() as i64) == 0 { errors.push(String::from("?")); }
        settled.insert(name.to_owned(), errors);
    }
    settled
}

fn theirs(sets: &collections::BTreeMap<String, collections::BTreeSet<String>>, own: &Ledger, callee: &str) -> Vec<String> {
    let mut errors: Vec<String> = vec![];
    if sets.contains_key(callee) {
        let set = match *nikaia_std::index::get(&sets, callee) { Some(__nikaia_value) => __nikaia_value, None => return errors };
        for error in set.iter() { errors.push(error.to_owned()); }
        return errors;
    }
    let contract = match *nikaia_std::index::get(&own.functions, callee) { Some(__nikaia_value) => __nikaia_value, None => return errors };
    for error in contract.fails_with.iter() { errors.push(error.to_owned()); }
    errors
}

pub fn error_type(names: &winnow_grammar::InternerContext, thrown: &Expr) -> Option<String> {
    match thrown {
        Expr::Path(segments) => if (segments.len() as i64) > 1 { Some(all_but_the_last(names, segments)) } else { None },
        Expr::Call { func, .. } => { let func = nikaia_std::boxed::open(func); error_type(names, func) },
        Expr::StructLit { name, .. } => { let name = *name; Some(struct_type(names.resolve(name))) },
        _ => None,
    }
}

fn all_but_the_last(names: &winnow_grammar::InternerContext, segments: &Vec<winnow_grammar::Symbol>) -> String {
    let mut written: String = String::from("");
    for k in 0..segments.len() as i64 - 1 {
        if k > 0 { written = format!("{}::", written); }
        let segment = names.resolve(*nikaia_std::index::get(&segments, nikaia_std::index::at(k)));
        written = format!("{}{}", written, segment);
    }
    written
}

fn struct_type(written: &str) -> String {
    let mut parts: Vec<String> = vec![];
    for part in written.split("::") { parts.push(part.to_owned()); }
    if (parts.len() as i64) < 2 { return written.to_owned(); }
    let mut ty: String = String::from("");
    for k in 0..parts.len() as i64 - 1 {
        if k > 0 { ty = format!("{}::", ty); }
        ty = format!("{}{}", ty, *nikaia_std::index::get(&parts, nikaia_std::index::at(k)));
    }
    ty
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Thrown {
    pub direct: collections::BTreeSet<String>,
    pub calls: collections::BTreeSet<String>,
    passes_on: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Contribution {
    pub call: Option<String>,
    pub errors: Vec<String>,
}

pub fn thrown_by(body: &Block, names: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, contribution_of: &impl Fn(&Expr) -> Contribution) -> Thrown {
    let mut out = Thrown { direct: collections::BTreeSet::new(), calls: collections::BTreeSet::new(), passes_on: false };
    thrown_in_block(body, names, holes_of, contribution_of, false, &mut out);
    out
}

fn thrown_in_block(block: &Block, names: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, contribution_of: &impl Fn(&Expr) -> Contribution, in_a_handler: bool, out: &mut Thrown) {
    for stmt in block.stmts.iter() {
        match &stmt.node {
            Stmt::Let { value, .. } => thrown_in(value, names, holes_of, contribution_of, in_a_handler, false, out),
            Stmt::Comptime { value, .. } => thrown_in(value, names, holes_of, contribution_of, in_a_handler, false, out),
            Stmt::Expr(value) => thrown_in(value, names, holes_of, contribution_of, in_a_handler, false, out),
            Stmt::Return(value) => thrown_in(match value { Some(__nikaia_value) => __nikaia_value, None => continue }, names, holes_of, contribution_of, in_a_handler, false, out),
            Stmt::Assign { target, value, .. } => {
                thrown_in(target, names, holes_of, contribution_of, in_a_handler, false, out);
                thrown_in(value, names, holes_of, contribution_of, in_a_handler, false, out);
            },
            Stmt::For { iter, .. } => thrown_in(iter, names, holes_of, contribution_of, in_a_handler, false, out),
            Stmt::While { cond, .. } => thrown_in(cond, names, holes_of, contribution_of, in_a_handler, false, out),
            _ => { },
        }
        match &stmt.node {
            Stmt::For { body, .. } => thrown_in_block(body, names, holes_of, contribution_of, in_a_handler, out),
            Stmt::While { body, .. } => thrown_in_block(body, names, holes_of, contribution_of, in_a_handler, out),
            Stmt::Let { value, .. } => thrown_in_blocks(value, names, holes_of, contribution_of, in_a_handler, out),
            Stmt::Comptime { value, .. } => thrown_in_blocks(value, names, holes_of, contribution_of, in_a_handler, out),
            Stmt::Expr(value) => thrown_in_blocks(value, names, holes_of, contribution_of, in_a_handler, out),
            Stmt::Return(value) => thrown_in_blocks(match value { Some(__nikaia_value) => __nikaia_value, None => continue }, names, holes_of, contribution_of, in_a_handler, out),
            Stmt::Assign { target, value, .. } => {
                thrown_in_blocks(target, names, holes_of, contribution_of, in_a_handler, out);
                thrown_in_blocks(value, names, holes_of, contribution_of, in_a_handler, out);
            },
            _ => { },
        }
    }
}

fn thrown_in(expr: &Expr, names: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, contribution_of: &impl Fn(&Expr) -> Contribution, in_a_handler: bool, caught: bool, out: &mut Thrown) {
    a_contribution(expr, names, contribution_of, in_a_handler, caught, out);
    for hole in holes_of(expr) { thrown_in(&hole, names, holes_of, contribution_of, in_a_handler, caught, out); }
    match expr {
        Expr::Call { func, args, config } => {
            let func = nikaia_std::boxed::open(func);
            thrown_in(func, names, holes_of, contribution_of, in_a_handler, caught, out);
            for arg in args.iter() { thrown_in(arg, names, holes_of, contribution_of, in_a_handler, caught, out); }
            for setting in config.iter() { thrown_in(&setting.value, names, holes_of, contribution_of, in_a_handler, caught, out); }
        },
        Expr::MethodCall { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            thrown_in(receiver, names, holes_of, contribution_of, in_a_handler, caught, out);
            for arg in args.iter() { thrown_in(arg, names, holes_of, contribution_of, in_a_handler, caught, out); }
            for setting in config.iter() { thrown_in(&setting.value, names, holes_of, contribution_of, in_a_handler, caught, out); }
        },
        Expr::SafeMethod { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            thrown_in(receiver, names, holes_of, contribution_of, in_a_handler, caught, out);
            for arg in args.iter() { thrown_in(arg, names, holes_of, contribution_of, in_a_handler, caught, out); }
            for setting in config.iter() { thrown_in(&setting.value, names, holes_of, contribution_of, in_a_handler, caught, out); }
        },
        Expr::Binary { lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            thrown_in(lhs, names, holes_of, contribution_of, in_a_handler, caught, out);
            thrown_in(rhs, names, holes_of, contribution_of, in_a_handler, caught, out);
        },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); thrown_in(expr, names, holes_of, contribution_of, in_a_handler, caught, out) },
        Expr::Try(inner) => { let inner = nikaia_std::boxed::open(inner); thrown_in(inner, names, holes_of, contribution_of, in_a_handler, caught, out) },
        Expr::Throw(inner) => { let inner = nikaia_std::boxed::open(inner); thrown_in(inner, names, holes_of, contribution_of, in_a_handler, caught, out) },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); thrown_in(expr, names, holes_of, contribution_of, in_a_handler, caught, out) },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); thrown_in(base, names, holes_of, contribution_of, in_a_handler, caught, out) },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); thrown_in(base, names, holes_of, contribution_of, in_a_handler, caught, out) },
        Expr::Index { base, index } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            thrown_in(base, names, holes_of, contribution_of, in_a_handler, caught, out);
            thrown_in(index, names, holes_of, contribution_of, in_a_handler, caught, out);
        },
        Expr::Range { start, end, .. } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end);
            thrown_in(start, names, holes_of, contribution_of, in_a_handler, caught, out);
            thrown_in(end, names, holes_of, contribution_of, in_a_handler, caught, out);
        },
        Expr::Tuple(parts) => { for part in parts.iter() { thrown_in(part, names, holes_of, contribution_of, in_a_handler, caught, out); } },
        Expr::Coalesce { value, fallback } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            thrown_in(value, names, holes_of, contribution_of, in_a_handler, caught, out);
            thrown_in(fallback, names, holes_of, contribution_of, in_a_handler, caught, out);
        },
        Expr::TryCatch { expr, handler } => {
            let expr = nikaia_std::boxed::open(expr);
            let into_the_handler = caught || !passes_on(handler, names, holes_of, contribution_of);
            thrown_in(expr, names, holes_of, contribution_of, in_a_handler, into_the_handler, out);
        },
        Expr::If { cond, .. } => { let cond = nikaia_std::boxed::open(cond); thrown_in(cond, names, holes_of, contribution_of, in_a_handler, caught, out) },
        Expr::Match { value, arms } => {
            let value = nikaia_std::boxed::open(value);
            thrown_in(value, names, holes_of, contribution_of, in_a_handler, caught, out);
            for arm in arms.iter() {
                maybe_thrown_in((arm.guard).as_ref(), names, holes_of, contribution_of, in_a_handler, caught, out);
                thrown_in(&arm.body, names, holes_of, contribution_of, in_a_handler, caught, out);
            }
        },
        Expr::StructLit { fields, .. } => { for field in fields.iter() { maybe_thrown_in((field.value).as_ref(), names, holes_of, contribution_of, in_a_handler, caught, out); } },
        Expr::ListLit { items, .. } => { for item in items.iter() { thrown_in(item, names, holes_of, contribution_of, in_a_handler, caught, out); } },
        Expr::With { base, fields, .. } => {
            let base = nikaia_std::boxed::open(base);
            thrown_in(base, names, holes_of, contribution_of, in_a_handler, caught, out);
            for field in fields.iter() { maybe_thrown_in((field.value).as_ref(), names, holes_of, contribution_of, in_a_handler, caught, out); }
        },
        Expr::Return(value) => { let value = nikaia_std::boxed::open(value); thrown_in(match value { Some(__nikaia_value) => __nikaia_value, None => return }, names, holes_of, contribution_of, in_a_handler, caught, out) },
        Expr::Select(arms) => { for arm in arms.iter() { thrown_in(&arm.value, names, holes_of, contribution_of, in_a_handler, caught, out); } },
        _ => { },
    }
}

fn maybe_thrown_in(expr: Option<&Expr>, names: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, contribution_of: &impl Fn(&Expr) -> Contribution, in_a_handler: bool, caught: bool, out: &mut Thrown) { thrown_in(match expr { Some(__nikaia_value) => __nikaia_value, None => return }, names, holes_of, contribution_of, in_a_handler, caught, out); }

fn thrown_in_blocks(expr: &Expr, names: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, contribution_of: &impl Fn(&Expr) -> Contribution, in_a_handler: bool, out: &mut Thrown) {
    match expr {
        Expr::Block(block) => thrown_in_block(block, names, holes_of, contribution_of, in_a_handler, out),
        Expr::Unsafe(block) => thrown_in_block(block, names, holes_of, contribution_of, in_a_handler, out),
        Expr::Overlap(block) => thrown_in_block(block, names, holes_of, contribution_of, in_a_handler, out),
        Expr::Closure { body, .. } => thrown_in_block(body, names, holes_of, contribution_of, in_a_handler, out),
        Expr::Call { func, args, config } => {
            let func = nikaia_std::boxed::open(func);
            thrown_in_blocks(func, names, holes_of, contribution_of, in_a_handler, out);
            for arg in args.iter() { thrown_in_blocks(arg, names, holes_of, contribution_of, in_a_handler, out); }
            for setting in config.iter() { thrown_in_blocks(&setting.value, names, holes_of, contribution_of, in_a_handler, out); }
        },
        Expr::MethodCall { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            thrown_in_blocks(receiver, names, holes_of, contribution_of, in_a_handler, out);
            for arg in args.iter() { thrown_in_blocks(arg, names, holes_of, contribution_of, in_a_handler, out); }
            for setting in config.iter() { thrown_in_blocks(&setting.value, names, holes_of, contribution_of, in_a_handler, out); }
        },
        Expr::SafeMethod { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            thrown_in_blocks(receiver, names, holes_of, contribution_of, in_a_handler, out);
            for arg in args.iter() { thrown_in_blocks(arg, names, holes_of, contribution_of, in_a_handler, out); }
            for setting in config.iter() { thrown_in_blocks(&setting.value, names, holes_of, contribution_of, in_a_handler, out); }
        },
        Expr::If { then_branch, else_branch, .. } => {
            thrown_in_block(then_branch, names, holes_of, contribution_of, in_a_handler, out);
            thrown_in_block(match else_branch { Some(__nikaia_value) => __nikaia_value, None => return }, names, holes_of, contribution_of, in_a_handler, out);
        },
        Expr::TryCatch { expr, handler } => {
            let expr = nikaia_std::boxed::open(expr);
            thrown_in_blocks(expr, names, holes_of, contribution_of, in_a_handler, out);
            thrown_in_block(handler, names, holes_of, contribution_of, true, out);
        },
        Expr::Match { arms, .. } => { for arm in arms.iter() { thrown_in_blocks(&arm.body, names, holes_of, contribution_of, in_a_handler, out); } },
        Expr::Select(arms) => { for arm in arms.iter() { thrown_in_block(&arm.body, names, holes_of, contribution_of, in_a_handler, out); } },
        _ => { },
    }
}

fn a_contribution(expr: &Expr, names: &winnow_grammar::InternerContext, contribution_of: &impl Fn(&Expr) -> Contribution, in_a_handler: bool, caught: bool, out: &mut Thrown) {
    let passing = the_caught_error(expr, names);
    if passing { out.passes_on = true; }
    if caught || in_a_handler && passing { return; }
    match expr {
        Expr::Throw(thrown) => {
            let thrown = nikaia_std::boxed::open(thrown);
            out.direct.insert(nikaia_std::index::or(error_type(names, thrown), || "?".into()));
        },
        _ => {
            let given = contribution_of(expr);
            let call = nikaia_std::index::or(given.call, || "".into());
            if (call.len() as i64) > 0 { out.calls.insert(call); }
            for error in given.errors.iter() { out.direct.insert(error.to_owned()); }
        },
    }
}

fn the_caught_error(expr: &Expr, names: &winnow_grammar::InternerContext) -> bool {
    match expr {
        Expr::Throw(thrown) => { let thrown = nikaia_std::boxed::open(thrown); match thrown {
            Expr::Variable(name) => { let name = *name; names.resolve(name) == "error" },
            _ => false,
        } },
        _ => false,
    }
}

fn passes_on(handler: &Block, names: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, contribution_of: &impl Fn(&Expr) -> Contribution) -> bool {
    let mut seen = Thrown { direct: collections::BTreeSet::new(), calls: collections::BTreeSet::new(), passes_on: false };
    thrown_in_block(handler, names, holes_of, contribution_of, false, &mut seen);
    seen.passes_on
}


// --- touch.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Reached {
    pub kind: String,
    pub named: Option<String>,
    pub unknown: bool,
    pub write: bool,
}

impl Reached {
    pub fn might_be_same(&self, other: &Reached) -> bool {
        if family(&self.kind) != family(&other.kind) { return false; }
        if self.unknown || other.unknown { return true; }
        let mine = match match self.named.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => return true };
        let theirs = match match other.named.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => return true };
        mine == theirs
    }
    pub fn conflicts_with(&self, other: &Reached) -> bool { (self.write || other.write) && self.might_be_same(other) }
}

fn family(kind: &str) -> String {
    if kind == "stderr" { return String::from("stdout"); }
    kind.to_owned()
}

pub fn touches_of(unknown: &collections::BTreeMap<String, bool>, outside: &collections::BTreeMap<String, Vec<Touch>>, calls: &collections::BTreeMap<String, collections::BTreeSet<String>>) -> collections::BTreeMap<String, Vec<Touch>> {
    let mut known: collections::BTreeMap<String, bool> = collections::BTreeMap::new();
    for (name, lost) in unknown.iter() {
        let lost = nikaia_std::num::value(lost);
        known.insert(name.to_owned(), !lost);
    }
    let mut changed = true;
    while changed {
        changed = false;
        for (name, called) in calls.iter() {
            let holds = nikaia_std::index::or(*nikaia_std::index::get(&known, name), || false);
            if !holds { continue; }
            let mut reaches_unknown = false;
            for callee in called.iter() {
                let theirs = nikaia_std::index::or(*nikaia_std::index::get(&known, callee), || false);
                if !theirs { reaches_unknown = true; }
            }
            if reaches_unknown {
                known.insert(name.to_owned(), false);
                changed = true;
            }
        }
    }
    let mut settled: collections::BTreeMap<String, Vec<Touch>> = collections::BTreeMap::new();
    for (name, holds) in known.iter() {
        let holds = nikaia_std::num::value(holds);
        if !holds { continue; }
        let mut found: Vec<Touch> = vec![];
        let mut seen: collections::BTreeSet<String> = collections::BTreeSet::new();
        let mut todo: Vec<String> = vec![name.to_owned()];
        while (todo.len() as i64) > 0 {
            let here = match todo.pop() { Some(__nikaia_value) => __nikaia_value, None => break };
            if seen.contains(&here) { continue; }
            seen.insert(here.to_owned());
            for touch in nikaia_std::index::or(match *nikaia_std::index::get(&outside, &here) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || vec![].into()) { found.push(touch); }
            for callee in nikaia_std::index::or(match *nikaia_std::index::get(&calls, &here) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || collections::BTreeSet::new().into()) { todo.push(callee); }
        }
        settled.insert(name.to_owned(), found);
    }
    settled
}


// --- traits.nika ---

pub fn check_impls(names: &winnow_grammar::InternerContext, items: &Vec<Spanned<Item>>, own: &Ledger) -> Vec<Finding> {
    let mut found: Vec<Finding> = vec![];
    for item in items.iter() {
        match &item.node {
            Item::Impl { trait_name, target, methods } => {
                let trait_name = *trait_name;
                let written_trait = match trait_name { Some(__nikaia_value) => __nikaia_value, None => continue };
                let named = names.resolve(written_trait).to_owned();
                for one in receivers(names, items, &named, methods) { found.push(one); }
                if !own.traits.contains_key(&named) { continue; }
                let declared = nikaia_std::index::or(match *nikaia_std::index::get(&own.traits, &named) {
                    Some(__nikaia_it) => Some(__nikaia_it.clone()),
                    None => None,
                }, || collections::BTreeSet::new().into());
                let target_name = names.resolve(target.name).to_owned();
                let mut given: Vec<String> = vec![];
                for method in methods.iter() {
                    match &method.node {
                        Item::Fn { name, .. } => {
                            let name = *name;
                            let symbol = match name { Some(__nikaia_value) => __nikaia_value, None => continue };
                            let written = names.resolve(symbol).to_owned();
                            given.push(written.to_owned());
                            if !declared.contains(&written) {
                                found.push(not_in_the_trait(&named, &target_name, &written, method.span.clone()));
                                continue;
                            }
                            for one in pausing(own, &named, &target_name, &written, method.span.clone()) { found.push(one); }
                        },
                        _ => { },
                    }
                }
                let mut missing: Vec<String> = vec![];
                for wanted in declared.iter() { if !given.contains(&wanted.to_owned()) { missing.push(wanted.to_owned()); } }
                if !missing.is_empty() { found.push(incomplete(&named, &target_name, &missing, item.span.clone())); }
            },
            _ => { },
        }
    }
    found
}

#[derive(Debug, Clone)]
struct Wanted {
    known: bool,
    receiver: Option<Receiver>,
}

fn receivers(names: &winnow_grammar::InternerContext, items: &Vec<Spanned<Item>>, trait_name: &str, methods: &Vec<Spanned<Item>>) -> Vec<Finding> {
    let mut found: Vec<Finding> = vec![];
    for method in methods.iter() {
        match &method.node {
            Item::Fn { name, receiver, .. } => {
                let name = *name;
                let symbol = match name { Some(__nikaia_value) => __nikaia_value, None => continue };
                let written = names.resolve(symbol).to_owned();
                let wanted = wanted_receiver(names, items, trait_name, &written);
                if !wanted.known || same_receiver(match wanted.receiver.as_ref() {
                    Some(__nikaia_it) => Some(__nikaia_it.clone()),
                    None => None,
                }, match receiver.as_ref() {
                    Some(__nikaia_it) => Some(__nikaia_it.to_owned()),
                    None => None,
                }) { continue; }
                let theirs = receiver_text(match wanted.receiver.as_ref() {
                    Some(__nikaia_it) => Some(__nikaia_it.clone()),
                    None => None,
                });
                let ours = receiver_text(match receiver {
                    Some(__nikaia_it) => Some(__nikaia_it.to_owned()),
                    None => None,
                });
                let notes: Vec<String> = vec![String::from("Callers go through the trait, so they pass the value the way the trait declares.")];
                found.push(refusal("NK1196", method.span.clone(), format!("`{}`'s `{}` takes {}, but this one takes {}.", trait_name, written, theirs, ours), notes, format!("Take it as {}, like `{}` declares.", theirs, trait_name)));
            },
            _ => { },
        }
    }
    found
}

fn wanted_receiver(names: &winnow_grammar::InternerContext, items: &Vec<Spanned<Item>>, trait_name: &str, method: &str) -> Wanted {
    for item in items.iter() {
        match &item.node {
            Item::Trait { name, methods, .. } => {
                let name = *name;
                if names.resolve(name) == trait_name {
                    for declared in methods.iter() {
                        if names.resolve(declared.node.name) == method {
                            return Wanted { known: true, receiver: match declared.node.receiver.as_ref() {
                                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                                None => None,
                            } };
                        }
                    }
                    return Wanted { known: false, receiver: None };
                }
            },
            _ => { },
        }
    }
    let shared = Receiver { is_ref: true, is_mut: false };
    let changed = Receiver { is_ref: true, is_mut: true };
    if trait_name == "Error" && method == "message" { return Wanted { known: true, receiver: Some(shared) }; }
    if trait_name == "Drop" && method == "drop" || trait_name == "Cleanup" && method == "cleanup" { return Wanted { known: true, receiver: Some(changed) }; }
    Wanted { known: false, receiver: None }
}

fn same_receiver(a: Option<Receiver>, b: Option<Receiver>) -> bool {
    if a.is_none() || b.is_none() { return a.is_none() && b.is_none(); }
    let one = nikaia_std::index::or(a, || Receiver { is_ref: false, is_mut: false });
    let other = nikaia_std::index::or(b, || Receiver { is_ref: false, is_mut: false });
    one.is_ref == other.is_ref && one.is_mut == other.is_mut
}

fn receiver_text(receiver: Option<Receiver>) -> String {
    let taken = match receiver { Some(__nikaia_value) => __nikaia_value, None => return String::from("no `self`") };
    if taken.is_ref && taken.is_mut { return String::from("`ref mut self`"); }
    if taken.is_ref { return String::from("`ref self`"); }
    if taken.is_mut { return String::from("`mut self`"); }
    String::from("`self`")
}

fn pausing(own: &Ledger, trait_name: &str, target: &str, method: &str, span: Span) -> Vec<Finding> {
    let mut found: Vec<Finding> = vec![];
    let implemented = format!("{}::{}", target, method);
    let declaring = format!("{}::{}", trait_name, method);
    if !own.functions.contains_key(&implemented) || !own.functions.contains_key(&declaring) { return found; }
    let contract = nikaia_std::index::or(match *nikaia_std::index::get(&own.functions, &implemented) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || FnContract::empty());
    let declared = nikaia_std::index::or(match *nikaia_std::index::get(&own.functions, &declaring) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || FnContract::empty());
    if declared.sync_claim.is_sync() && !contract.sync_claim.is_sync() {
        let notes: Vec<String> = vec![String::from("`sync` in a trait promises that every implementation never pauses. (The opposite is fine: a body that never pauses can implement a method that may.)")];
        found.push(refusal("NK1129", span.clone(), format!("`{}::{}` can pause, but `{}` declares `{}` as `sync`.", target, method, trait_name, method), notes, format!("Remove `sync` from `{}`'s `{}`, or take out what pauses in the body, such as a file read, a sleep or a `.join()`.", trait_name, method)));
    }
    if declared.fails_with.is_empty() && !contract.fails_with.is_empty() {
        let notes: Vec<String> = vec![String::from("A trait method without `throws` promises that no implementation fails. (The opposite is fine: a body that can't fail can implement one with `throws`.)")];
        found.push(refusal("NK1140", span, format!("`{}::{}` can fail, but `{}` declares `{}` without `throws`.", target, method, trait_name, method), notes, format!("Add `throws` to `{}`'s `{}`, or handle the failure in the body with `catch`.", trait_name, method)));
    }
    found
}

fn not_in_the_trait(trait_name: &str, target: &str, method: &str, span: Span) -> Finding {
    let notes: Vec<String> = vec![format!("`impl {} for {}` can only hold `{}`'s methods. The type's own methods go in a separate `impl {}`.", trait_name, target, trait_name, target)];
    refusal("NK1130", span, format!("`{}` has no method called `{}`.", trait_name, method), notes, format!("Move it to `impl {}`, or add `{}` to `{}` if every type that implements it should have one.", target, method, trait_name))
}

fn incomplete(trait_name: &str, target: &str, missing: &Vec<String>, span: Span) -> Finding {
    let mut listed: String = String::from("");
    for at in 0..missing.len() as i64 {
        if at > 0 { listed.push_str(", "); }
        let one = nikaia_std::index::get(&missing, nikaia_std::index::at(at));
        let quoted = format!("`{}`", one);
        listed.push_str(&quoted);
    }
    let pronoun = if (missing.len() as i64) == 1 { "it" } else { "them" };
    let notes: Vec<String> = vec![String::from("A trait promises that all its methods are there, which is what lets code call them through a bound.")];
    refusal("NK1130", span, format!("`{}` is missing {} from `{}`.", target, listed, trait_name), notes, format!("Add {} to this `impl`, or remove {} from `{}`.", listed, pronoun, trait_name))
}


// --- trust.nika ---

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Wrote {
    Anywhere,
    TheFilesystemRoot,
}

pub fn spelled(wrote: &Wrote) -> String {
    match wrote {
        Wrote::Anywhere => String::from("Anywhere"),
        Wrote::TheFilesystemRoot => String::from("Dir(\"/\") - which is every directory"),
    }
}

pub fn written_root(names: &winnow_grammar::InternerContext, arg: &Expr) -> Option<Wrote> {
    match arg {
        Expr::Path(segments) => if ends_with_variant(names, segments, "Anywhere") { Some(Wrote::Anywhere) } else { None },
        Expr::Call { func, args, .. } => { let func = nikaia_std::boxed::open(func); the_whole_filesystem(names, func, args) },
        _ => None,
    }
}

fn the_whole_filesystem(names: &winnow_grammar::InternerContext, func: &Expr, args: &Vec<Expr>) -> Option<Wrote> {
    let is_dir = match func {
        Expr::Path(segments) => ends_with_variant(names, segments, "Dir"),
        _ => false,
    };
    if !is_dir || (args.len() as i64) == 0 { return None; }
    match *nikaia_std::index::get(&args, 0) {
        Expr::LitStr { ref text, .. } => if text == "/" { Some(Wrote::TheFilesystemRoot) } else { None },
        _ => None,
    }
}

fn ends_with_variant(names: &winnow_grammar::InternerContext, segments: &Vec<winnow_grammar::Symbol>, variant: &str) -> bool {
    let n = segments.len() as i64;
    n >= 2 && names.resolve(*nikaia_std::index::get(&segments, nikaia_std::index::at(n - 2))) == "Root" && names.resolve(*nikaia_std::index::get(&segments, nikaia_std::index::at(n - 1))) == variant
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Reason {
    pub source: String,
    pub untrusted: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Place {
    pub line: i64,
    pub column: i64,
    pub entry: String,
    pub wrote: Wrote,
}

pub fn render(untrusted: bool, reasons: &[Reason], places: &[Place], path: &str) -> String {
    let mut out = format!("input provenance: {}\n", provenance(untrusted));
    if (reasons.len() as i64) == 0 { out.push_str("    no source is read, so nothing entered from outside\n"); }
    for reason in reasons.iter() { out.push_str(&format!("    {} is {}\n", reason.source, provenance(reason.untrusted))); }
    let hash = if untrusted { "keyed, per-process random seed - key choice cannot be aimed at the table" } else { "fast, fixed seed - no adversary chooses these keys" };
    out.push_str(&format!("hash for a map keyed by the input: {}\n", hash));
    out.push_str("file access with no root to check against:\n");
    if (places.len() as i64) == 0 { out.push_str("    none - every path here names a directory it may not leave\n"); }
    for place in places.iter() { out.push_str(&format!("    {}:{}:{}  {} writes {}\n", path, place.line, place.column, place.entry, spelled(&place.wrote))); }
    out
}

fn provenance(untrusted: bool) -> String { if untrusted { String::from("untrusted") } else { String::from("trusted") } }


// --- ty.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Ty {
    Unknown,
    Named { name: String, args: Vec<Ty>, view: bool },
    Tuple(Vec<Ty>),
    Pointed { item: Box<Ty>, slice: bool, mutable: bool },
    Count(i64),
    Var { name: String, view: bool },
    Fn { params: Vec<Ty>, result: Box<Option<Ty>>, is_sync: bool, can_throw: bool },
    Nullable(Box<Ty>),
    Seq { item: Box<Ty>, is_sync: bool, pauses: bool, can_throw: bool, parallel: bool, shape: Shape },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Shape {
    pub ends: bool,
    pub sized: bool,
    pub replays: bool,
}

impl Shape {
    pub fn none() -> Shape { Shape { ends: false, sized: false, replays: false } }
    pub fn meets(&self, wanted: &Shape) -> bool { (self.missing(wanted).len() as i64) == 0 }
    pub fn missing(&self, wanted: &Shape) -> Vec<String> {
        let mut words: Vec<String> = vec![];
        if wanted.ends && !self.ends { words.push(ENDS.to_owned()); }
        if wanted.sized && !self.sized { words.push(SIZED.to_owned()); }
        if wanted.replays && !self.replays { words.push(REPLAYS.to_owned()); }
        words
    }
}

pub const ENDS: &str = "ends";

pub const SIZED: &str = "sized";

pub const REPLAYS: &str = "replays";

pub const SEQ: &str = "Seq";

pub const PAR: &str = "Par";

pub const PAUSES: &str = "pauses";

pub const ARRAY: &str = "Array";

const ARRAY_OPEN: &str = "Array[";

const ARRAY_OPEN_LENGTH: i64 = 6;

pub const TEXT: &str = "String";

pub const TEXT_VIEW: &str = "str";

impl Ty {
    pub fn text(&self) -> String { text(self) }
}

pub fn text(ty: &Ty) -> String {
    match ty {
        Ty::Unknown => String::from("?"),
        Ty::Count(n) => { let n = *n; format!("{}", n) },
        Ty::Pointed { item, slice, mutable } => { let item = nikaia_std::boxed::open(item); let mutable = *mutable; let slice = *slice; pointed(item, slice, mutable) },
        Ty::Tuple(parts) => format!("({})", listed(parts)),
        Ty::Fn { params, result, is_sync, can_throw } => { let result = nikaia_std::boxed::open(result); let can_throw = *can_throw; let is_sync = *is_sync; code(params, (result).as_ref(), is_sync, can_throw) },
        Ty::Var { name, view } => { let view = *view; if view { format!("ref ${}", name) } else { format!("${}", name) } },
        Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); format!("{}?", text(inner)) },
        Ty::Named { name, args, view } => { let view = *view; named_text(name, args, view) },
        Ty::Seq { item, is_sync, pauses, can_throw, parallel, shape } => { let item = nikaia_std::boxed::open(item); let can_throw = *can_throw; let is_sync = *is_sync; let parallel = *parallel; let pauses = *pauses; sequence(item, is_sync, pauses, can_throw, parallel, shape) },
    }
}

fn listed(parts: &[Ty]) -> String {
    let mut out: String = String::from("");
    for part in parts.iter() {
        if !out.is_empty() { out.push_str(", "); }
        out.push_str(&text(part));
    }
    out
}

fn pointed(item: &Ty, slice: bool, mutable: bool) -> String {
    let mut out: String = String::from("ref ");
    if mutable { out.push_str("mut "); }
    if !slice {
        out.push_str(&text(item));
        return out;
    }
    let written = match item {
        Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); format!("{}[{}]?", ARRAY, text(inner)) },
        _ => format!("{}[{}]", ARRAY, text(item)),
    };
    out.push_str(&written);
    out
}

fn code(params: &[Ty], result: Option<&Ty>, is_sync: bool, can_throw: bool) -> String {
    let mut out = format!("fn({})", listed(params));
    if result.is_some() {
        let returned = nikaia_std::index::or(match result {
            Some(__nikaia_it) => Some(__nikaia_it.text()),
            None => None,
        }, || "".into());
        out.push_str(&format!(" -> {}", returned));
    }
    if is_sync { out.push_str(" sync"); }
    if can_throw { out.push_str(" throws"); }
    out
}

fn named_text(name: &str, args: &[Ty], view: bool) -> String {
    let mut out: String = if view { String::from("ref ") } else { String::from("") };
    if view && name == TEXT_VIEW { out.push_str(TEXT); } else { out.push_str(name); }
    if (args.len() as i64) > 0 { out.push_str(&format!("[{}]", listed(args))); }
    out
}

fn sequence(item: &Ty, is_sync: bool, pauses: bool, can_throw: bool, parallel: bool, shape: &Shape) -> String {
    let word = if parallel { PAR } else { SEQ };
    let mut out = format!("{}[{}]", word, text(item));
    if is_sync { out.push_str(" sync"); }
    if pauses { out.push_str(&format!(" {}", PAUSES)); }
    if can_throw { out.push_str(" throws"); }
    for word in Shape::none().missing(shape) { out.push_str(&format!(" {}", word)); }
    out
}

pub fn parse(written: &str) -> Ty {
    let trimmed = written.trim();
    if (trimmed.len() as i64) == 0 || trimmed == "?" { return Ty::Unknown; }
    let count = text::parse_i64(trimmed);
    if count.is_some() { return Ty::Count(nikaia_std::index::or(count, || 0)); }
    let viewed = a_view_of(trimmed);
    let is_a_view = viewed.is_some();
    let marked: String = nikaia_std::index::or(viewed, || "".into());
    if is_a_view {
        let pointer = pointed_at(&marked);
        if pointer.is_some() { return nikaia_std::index::or(pointer, || Ty::Unknown); }
    }
    if trimmed.ends_with("?") { return Ty::Nullable(Box::new(parse(&cut(trimmed, 0, 1)))); }
    if trimmed.starts_with("(") && trimmed.ends_with(")") { return Ty::Tuple(each(&split_args(&cut(trimmed, 1, 1)))); }
    if trimmed.starts_with("fn(") {
        let code = a_function(trimmed);
        if code.is_some() { return nikaia_std::index::or(code, || Ty::Unknown); }
    }
    let sequence = a_sequence(trimmed, SEQ, false);
    if sequence.is_some() { return nikaia_std::index::or(sequence, || Ty::Unknown); }
    let parallel = a_sequence(trimmed, PAR, true);
    if parallel.is_some() { return nikaia_std::index::or(parallel, || Ty::Unknown); }
    if is_a_view { return a_name(marked.trim(), true); }
    a_name(trimmed, false)
}

pub fn split_args(written: &str) -> Vec<String> {
    let mut parts: Vec<String> = vec![];
    let mut depth = 0;
    let mut current: String = String::from("");
    for c in written.chars() {
        if c == '[' || c == '(' {
            depth += 1;
            current.push(c);
        } else if c == ']' || c == ')' {
            if depth > 0 { depth -= 1; }
            current.push(c);
        } else if c == ',' && depth == 0 {
            parts.push(current.trim().to_owned());
            current = String::from("");
        } else { current.push(c); }
    }
    if (current.trim().len() as i64) > 0 { parts.push(current.trim().to_owned()); }
    parts
}

pub fn a_view_of(written: &str) -> Option<String> {
    if written.starts_with("ref(") {
        let c: Vec<char> = nikaia_std::list::chars(written.chars());
        let close = closing(&c, 4, ')');
        if close >= 0 {
            let rest = between(&c, close + 1, c.len() as i64);
            return Some(rest.trim_start().to_owned());
        }
    }
    if written.starts_with("ref ") {
        let rest = cut(written, 4, 0);
        return Some(rest.trim_start().to_owned());
    }
    if written.starts_with("&") {
        let rest = cut(written, 1, 0);
        return Some(rest.trim_start().to_owned());
    }
    None
}

fn each(parts: &[String]) -> Vec<Ty> {
    let mut read: Vec<Ty> = vec![];
    for part in parts.iter() { read.push(parse(part)); }
    read
}

fn between(c: &[char], from: i64, to: i64) -> String {
    let mut out: String = String::from("");
    for k in from..to { out.push(*nikaia_std::index::get(&c, nikaia_std::index::at(k))); }
    out
}

fn cut(written: &str, front: i64, back: i64) -> String {
    let c: Vec<char> = nikaia_std::list::chars(written.chars());
    between(&c, front, c.len() as i64 - back)
}

fn closing(c: &[char], from: i64, closer: char) -> i64 {
    let mut depth = 0;
    for at in from..c.len() as i64 {
        let ch = *nikaia_std::index::get(&c, nikaia_std::index::at(at));
        if ch == '(' || ch == '[' { depth += 1; } else if ch == closer {
            if depth == 0 { return at; }
            depth -= 1;
        } else if ch == ')' || ch == ']' {
            if depth == 0 { return -1; }
            depth -= 1;
        }
    }
    -1
}

fn word_off(tail: &str, word: &str) -> Option<String> {
    if !tail.ends_with(word) { return None; }
    let c: Vec<char> = nikaia_std::list::chars(tail.chars());
    let w: Vec<char> = nikaia_std::list::chars(word.chars());
    let shorter = between(&c, 0, c.len() as i64 - w.len() as i64);
    if (shorter.len() as i64) == 0 { return Some(shorter); }
    if (*nikaia_std::index::get(&c, nikaia_std::index::at(c.len() as i64 - w.len() as i64 - 1))).is_whitespace() { return Some(shorter.trim_end().to_owned()); }
    None
}

fn pointed_at(viewed: &str) -> Option<Ty> {
    let __keep_frame = nikaia_std::tether::Keep::new();
    let mut rest: String = viewed.to_owned();
    let mut mutable = false;
    if rest.starts_with("mut ") {
        mutable = true;
        let shorter = __keep_frame.put(cut(&rest, 4, 0));
        rest = shorter.trim_start().to_owned();
    }
    let mut absent = false;
    if rest.ends_with("?") {
        absent = true;
        let shorter = __keep_frame.put(cut(&rest, 0, 1));
        rest = shorter.trim_end().to_owned();
    }
    let mut slice = false;
    let mut inner: String = String::from("");
    if rest.starts_with(ARRAY_OPEN) && rest.ends_with("]") {
        let args = cut(&rest, ARRAY_OPEN_LENGTH, 1);
        if (split_args(&args).len() as i64) == 1 {
            slice = true;
            inner = args;
        }
    }
    if !slice && rest.starts_with("[") && rest.ends_with("]") {
        slice = true;
        inner = cut(&rest, 1, 1);
    }
    if !mutable && !slice { return None; }
    if !slice { inner = rest.to_owned(); }
    let item = parse(&inner);
    if absent { return Some(Ty::Pointed { item: Box::new(Ty::Nullable(Box::new(item))), slice, mutable }); }
    Some(Ty::Pointed { item: Box::new(item), slice, mutable })
}

fn a_function(written: &str) -> Option<Ty> {
    let c: Vec<char> = nikaia_std::list::chars(written.chars());
    let close = closing(&c, 3, ')');
    if close < 0 { return None; }
    let after = between(&c, close + 1, c.len() as i64);
    let mut tail: String = after.trim().to_owned();
    let mut is_sync = false;
    let mut can_throw = false;
    while (tail.len() as i64) > 0 {
        let without_throws = word_off(&tail, "throws");
        if without_throws.is_some() {
            can_throw = true;
            tail = nikaia_std::index::or(without_throws, || "".into());
            continue;
        }
        let without_sync = word_off(&tail, "sync");
        if without_sync.is_some() {
            is_sync = true;
            tail = nikaia_std::index::or(without_sync, || "".into());
            continue;
        }
        break;
    }
    let params = each(&split_args(&between(&c, 3, close)));
    if tail.starts_with("->") {
        let result = parse(&cut(&tail, 2, 0));
        return Some(Ty::Fn { params, result: Box::new(Some(result)), is_sync, can_throw });
    }
    Some(Ty::Fn { params, result: Box::new(None), is_sync, can_throw })
}

fn a_sequence(written: &str, word: &str, parallel: bool) -> Option<Ty> {
    if !written.starts_with(word) { return None; }
    let w: Vec<char> = nikaia_std::list::chars(word.chars());
    let after_word = cut(written, w.len() as i64, 0);
    let rest: String = after_word.trim_start().to_owned();
    if !rest.starts_with("[") { return None; }
    let c: Vec<char> = nikaia_std::list::chars(rest.chars());
    let close = closing(&c, 1, ']');
    if close < 0 { return None; }
    let after = between(&c, close + 1, c.len() as i64);
    let mut tail: String = after.trim().to_owned();
    let mut is_sync = false;
    let mut pauses = false;
    let mut can_throw = false;
    let mut ends = false;
    let mut sized = false;
    let mut replays = false;
    while (tail.len() as i64) > 0 {
        let without_ends = word_off(&tail, ENDS);
        if without_ends.is_some() {
            ends = true;
            tail = nikaia_std::index::or(without_ends, || "".into());
            continue;
        }
        let without_sized = word_off(&tail, SIZED);
        if without_sized.is_some() {
            sized = true;
            tail = nikaia_std::index::or(without_sized, || "".into());
            continue;
        }
        let without_replays = word_off(&tail, REPLAYS);
        if without_replays.is_some() {
            replays = true;
            tail = nikaia_std::index::or(without_replays, || "".into());
            continue;
        }
        let without_throws = word_off(&tail, "throws");
        if without_throws.is_some() {
            can_throw = true;
            tail = nikaia_std::index::or(without_throws, || "".into());
            continue;
        }
        let without_sync = word_off(&tail, "sync");
        if without_sync.is_some() {
            is_sync = true;
            tail = nikaia_std::index::or(without_sync, || "".into());
            continue;
        }
        let without_pauses = word_off(&tail, PAUSES);
        if without_pauses.is_some() {
            pauses = true;
            tail = nikaia_std::index::or(without_pauses, || "".into());
            continue;
        }
        break;
    }
    if is_sync && pauses { return None; }
    if (tail.len() as i64) > 0 { return None; }
    let item = parse(&between(&c, 1, close));
    let shape = Shape { ends, sized, replays };
    Some(Ty::Seq { item: Box::new(item), is_sync, pauses, can_throw, parallel, shape })
}

fn a_name(rest: &str, view: bool) -> Ty {
    if rest.starts_with("$") && (rest.len() as i64) > 1 { return Ty::Var { name: cut(rest, 1, 0), view }; }
    if view && rest == TEXT { return Ty::Named { name: TEXT_VIEW.to_owned(), args: vec![], view: true }; }
    if !rest.ends_with("]") { return Ty::Named { name: rest.to_owned(), args: vec![], view }; }
    let c: Vec<char> = nikaia_std::list::chars(rest.chars());
    let mut open: i64 = -1;
    for at in 0..c.len() as i64 { if open < 0 && *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '[' { open = at; } }
    if open >= 0 {
        let named_text = between(&c, 0, open);
        return Ty::Named { name: named_text.trim().to_owned(), args: each(&split_args(&between(&c, open + 1, c.len() as i64 - 1))), view };
    }
    Ty::Named { name: rest.to_owned(), args: vec![], view }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Provenance {
    Trusted,
    Untrusted,
}

impl Provenance {
    pub fn join(self, other: Provenance) -> Provenance {
        if self == Provenance::Untrusted || other == Provenance::Untrusted { return Provenance::Untrusted; }
        Provenance::Trusted
    }
    pub fn as_str(self) -> String {
        match self {
            Provenance::Trusted => String::from("trusted"),
            Provenance::Untrusted => String::from("untrusted"),
        }
    }
}

